'use strict';
const MD=window.MARKET_DATA, STORAGE='agromitra.market.prototype.v1';
const ICONS={leaf:'<path d="M19 4c-9-1-15 3-13 10 2 5 11 3 13-10Z"/><path d="M5 20 15 9M9 14l-1-4m5 1 4 1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',back:'<path d="m15 5-7 7 7 7M8 12h13"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4L19 6"/>',heart:'<path d="M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-4 4 2 10 8 15 6-5 12-11 8-15Z"/>',chat:'<path d="M20 16V5H4v14l5-3Z"/><path d="M8 9h8M8 12h5"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 20h4"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M10 21v-7h4v7"/>',request:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 2h6v4H9ZM9 11h6M9 15h6"/>',deal:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/>',truck:'<path d="M2 6h12v12H2ZM14 10h4l4 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',doc:'<path d="M5 3h9l5 5v13H5ZM14 3v6h5M9 13h6M9 17h6"/>',star:'<path d="m12 3 3 6 6 1-4.5 4.5 1 6L12 18l-5.5 2.5 1-6L3 10l6-1Z"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',send:'<path d="m3 3 19 9-19 9 4-9ZM7 12h15"/>',wallet:'<path d="M3 7V4h15v3M3 7h18v14H3ZM15 12h6v5h-6Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18M8 14h1M13 14h1M8 18h1"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 10 7-4M8 14l7 4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',chart:'<path d="M4 3v18h17M8 17v-5M13 17V7M18 17V4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 1c0 2-3 2-3 5M12 17h.01"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3Z"/><circle cx="12" cy="14" r="4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.leaf}</svg>`;
const esc=(v)=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const clone=(x)=>JSON.parse(JSON.stringify(x));
const today=()=>new Date().toISOString().slice(0,10);
const future=(days)=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);
const uid=(p)=>p+Date.now().toString(36).toUpperCase()+Math.random().toString(36).slice(2,5).toUpperCase();
function initialState(){return {version:1,profile:{name:'Demo Buyer',role:'buyer',business:'Individual',city:'Guntur',language:'en',onboarded:false},listings:clone(MD.listings).map((p,i)=>({...p,status:'active',created:Date.now()-i*600000,expires:future(['produce','dairy','aqua'].includes(p.cat)?7:30),own:false,identity:'sample'})),requests:clone(MD.requests).map(r=>({...r,expires:future(r.days),own:false,status:'open'})),saved:[],deals:[{id:'D301',listingId:'L101',title:'Sona Masoori paddy',cat:'crops',image:'paddy',quantity:10,unit:'quintal',price:2600,buyer:'Demo Buyer',seller:'Ravi Farmer Collective',location:'Guntur',stage:'quote',created:Date.now(),payments:[],terms:null,inspection:null,delivery:null},{id:'D302',listingId:'L110',title:'Jersey cross dairy cow',cat:'cattle',image:'cow',quantity:1,unit:'animal',price:68000,buyer:'Demo Buyer',seller:'Sree Dairy Farm',location:'Mangalagiri',stage:'inspection',created:Date.now(),payments:[],terms:null,inspection:null,delivery:null}],chats:[{id:'C301',listingId:'L109',party:'Sree Dairy Farm',messages:[{mine:false,text:'Welcome! You can arrange a farm visit and observe milking before deciding.',demo:true,time:Date.now()}]}],notifications:[{id:'N1',title:'Sample buyer requirements are ready',te:'నమూనా కొనుగోలుదారుల అవసరాలు సిద్ధంగా ఉన్నాయి',route:'requests',read:false},{id:'N2',title:'Try the dairy inspection flow',te:'పశువుల తనిఖీ ప్రక్రియను ప్రయత్నించండి',route:'deal',params:{id:'D302'},read:false},{id:'N3',title:'Your data stays on this device',te:'మీ డేటా ఈ పరికరంలోనే ఉంటుంది',route:'help',read:false}],tickets:[],ratings:[],subscription:null,promotions:[]};}
let state;
try{const raw=JSON.parse(localStorage.getItem(STORAGE));state=raw&&raw.version===1&&Array.isArray(raw.listings)?raw:initialState();}catch(e){state=initialState();}
const L=(e,t)=>state.profile.language==='te'&&t?t:e;
const cat=(id)=>MD.categories.find(c=>c.id===id)||MD.categories[0];
const title=(p)=>L(p.title,p.te);
const unit=(u)=>L(({quintal:'quintal',kg:'kg',animal:'animal',bird:'bird',egg:'egg',litre:'litre',fish:'fish seed'})[u]||u,({quintal:'క్వింటాల్',kg:'కిలో',animal:'జంతువు',bird:'కోడి',egg:'గుడ్డు',litre:'లీటరు',fish:'చేప పిల్ల'})[u]);
const seller=(id)=>id==='ME'?{name:state.profile.name,te:state.profile.name,initials:state.profile.name.slice(0,2).toUpperCase(),type:'Your demo profile',location:state.profile.city}:MD.sellers.find(s=>s.id===id)||MD.sellers[0];
const getListing=(id)=>state.listings.find(p=>p.id===id);
const getRequest=(id)=>state.requests.find(r=>r.id===id);
const getDeal=(id)=>state.deals.find(d=>d.id===id);
const dealTotal=(d)=>Math.round(d.quantity*d.price*100)/100;
const paid=(d)=>d.payments.reduce((a,p)=>a+p.amount,0);
const remaining=(d)=>d.stage==='cancelled'?0:Math.max(0,dealTotal(d)-paid(d));
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch(e){toast(L('Storage is full. Changes are available until the app closes.','నిల్వ నిండింది. యాప్ మూసే వరకు మార్పులు ఉంటాయి.'));}}
function notify(label,te,route='account',params={}){state.notifications.unshift({id:uid('N'),title:label,te,route,params,read:false});}
const ui={route:state.profile.onboarded?'home':'welcome',params:{},stack:[],filters:{cat:'all',query:'',distance:0,price:0,quality:'all',sort:'recent',location:'All'},requestCat:'all',requestTab:'all',dealTab:'active',draft:null,requestDraft:null};
let toastTimer;
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3100);}
function go(route,params={},replace=false){closeModal();if(!replace&&ui.route!==route)ui.stack.push({route:ui.route,params:ui.params});else if(!replace&&ui.route===route&&JSON.stringify(params)!==JSON.stringify(ui.params))ui.stack.push({route:ui.route,params:ui.params});ui.route=route;ui.params=params;render();window.scrollTo(0,0);}
function tab(route){ui.stack=[];go(route,{},true);}
function back(){closeModal();if(ui.stack.length){const x=ui.stack.pop();ui.route=x.route;ui.params=x.params;render();window.scrollTo(0,0);}else tab('home');}
window.handleAndroidBack=function(){if(document.getElementById('modal-root').innerHTML){closeModal();return true;}if(ui.route==='sell'&&Number(ui.params.step)>1){captureDraft();go('sell',{step:ui.params.step-1},true);return true;}if(ui.stack.length){back();return true;}if(!['home','welcome'].includes(ui.route)){tab('home');return true;}return false;};
function closeModal(){document.getElementById('modal-root').innerHTML='';}
function modal(heading,html){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><div class="row"><h2>${esc(heading)}</h2><button class="icon-button" data-action="close-modal" aria-label="${L('Close','మూసివేయండి')}">${icon('close')}</button></div>${html}</section></div>`;}
const btn=(text,action,id='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const note=(en,te,gold=false)=>`<div class="notice ${gold?'gold':''}">${L(en,te)}</div>`;
const selectOptions=(arr,value)=>arr.map(o=>{const v=typeof o==='string'?o:o[0],text=typeof o==='string'?o:o[1];return `<option value="${esc(v)}" ${v==value?'selected':''}>${esc(text)}</option>`;}).join('');
function field(label,name,value='',type='text',extra='',hint=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;}
function select(label,name,options,value){return `<label class="field"><span>${label}</span><select name="${name}">${selectOptions(options,value)}</select></label>`;}
function textarea(label,name,value='',extra=''){return `<label class="field"><span>${label}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
const errorBox=()=>'<div class="form-error" id="form-error" role="alert"></div>';
const submit=(text)=>`<button class="btn" type="submit">${text}</button>`;
function error(text){const el=document.getElementById('form-error');if(el)el.textContent=text;else toast(text);return false;}
function header(text,sub='',home=false){return `<header class="topbar">${home?`<div class="brand"><div class="brandmark">${icon('leaf')}</div><div class="brandname">Agromitra<span>MARKET</span></div></div>`:`<button class="icon-button" data-action="back" aria-label="${L('Back','వెనక్కి')}">${icon('back')}</button><div class="titlebar"><strong>${text}</strong>${sub?`<small>${sub}</small>`:''}</div>`}${home?`<button class="icon-button" data-action="inbox" aria-label="${L('Messages','సందేశాలు')}">${icon('chat')}</button><button class="icon-button" data-action="notifications" aria-label="${L('Notifications','నోటిఫికేషన్లు')}">${icon('bell')}${state.notifications.some(n=>!n.read)?'<i class="dot"></i>':''}</button>`:''}</header><div class="prototype">${L('OFFLINE PROTOTYPE · Sample listings and simulated transactions','ఆఫ్‌లైన్ నమూనా · నమూనా లిస్టింగ్‌లు మరియు లావాదేవీలు')}</div>`;}
function nav(active){return `<nav class="nav" aria-label="Main navigation">${[['home','home',L('Explore','మార్కెట్')],['requests','request',L('Requests','అవసరాలు')],['sell','plus',L('Sell','అమ్మండి')],['deals','deal',L('Deals','ఒప్పందాలు')],['account','user',L('Account','ఖాతా')]].map(([r,i,t])=>`<button data-action="nav" data-id="${r}" class="${r===active?'active':''}">${r==='sell'?`<span class="sell-icon">${icon(i)}</span>`:icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function shell(text,html,active='',home=false,sub='',footer=''){return header(text,sub,home)+`<main>${html}</main>`+(footer|| (active?nav(active):''));}
function empty(h,p,button=''){return `<div class="empty"><div class="empty-icon">${icon('leaf')}</div><h3>${h}</h3><p>${p}</p>${button}</div>`;}
function qualityTag(p){if(p.quality==='samplevet')return `<span class="tag blue">${icon('doc')}${L('Sample vet report','నమూనా వెట్ రిపోర్ట్')}</span>`;if(p.quality==='samplelab')return `<span class="tag blue">${icon('doc')}${L('Sample lab report','నమూనా ల్యాబ్ రిపోర్ట్')}</span>`;return `<span class="tag">${L('Seller declared','విక్రేత తెలిపినది')}</span>`;}
function card(p){return `<article class="product"><button class="saved ${state.saved.includes(p.id)?'on':''}" data-action="save-listing" data-id="${p.id}" aria-label="${L('Save','సేవ్')} ${esc(title(p))}">${icon('heart')}</button><div class="product-media" data-action="detail" data-id="${p.id}" role="button" tabindex="0" aria-label="${esc(title(p))}"><img src="art/${p.image}.svg" alt="${esc(title(p))}"><span class="art-credit">${L('Illustration','చిత్ర నమూనా')}</span></div><div class="product-body"><button data-action="detail" data-id="${p.id}" style="padding:0;text-align:left;width:100%"><h3>${esc(title(p))}</h3></button><div class="price">${money(p.price)} <small>/ ${unit(p.unit)}</small></div><div class="meta">${p.quantity.toLocaleString('en-IN')} ${unit(p.unit)} ${L('available','లభ్యం')}</div><div class="meta">${esc(p.location)} · ${p.distance} ${L('km demo','కి.మీ నమూనా')}</div>${p.promoted?`<span class="tag gold">${L('Sponsored · demo','ప్రాయోజితం · నమూనా')}</span>`:qualityTag(p)}</div></article>`;}
function available(p){return p.status==='active'&&p.expires>=today();}
function filtered(){const f=ui.filters;return state.listings.filter(p=>available(p)&&(f.cat==='all'||p.cat===f.cat)&&(!f.query||(p.title+' '+(p.te||'')+' '+p.location+' '+p.sub).toLowerCase().includes(f.query.toLowerCase()))&&(!f.distance||p.distance<=f.distance)&&(!f.price||p.price<=f.price)&&(!f.quantity||p.quantity>=f.quantity)&&(!f.unit||f.unit==='all'||p.unit===f.unit)&&(f.location==='All'||p.location===f.location)&&(f.quality==='all'||(f.quality==='reports'&&['samplevet','samplelab'].includes(p.quality)))).sort((a,b)=>f.sort==='low'?a.price-b.price:f.sort==='high'?b.price-a.price:f.sort==='near'?a.distance-b.distance:b.created-a.created);}
function categoryChips(action='browse-cat',selected=ui.filters.cat){return `<div class="chips"><button class="chip ${selected==='all'?'active':''}" data-action="${action}" data-id="all">${L('All','అన్నీ')}</button>${MD.categories.map(c=>`<button class="chip ${selected===c.id?'active':''}" data-action="${action}" data-id="${c.id}">${L(c.name,c.te)}</button>`).join('')}</div>`;}
function home(){const sellerMode=state.profile.role==='seller';return shell('',`<div class="location-row"><button data-action="location">${icon('pin')}${esc(state.profile.city)} ${icon('down')}</button><button class="role-pill" data-action="switch-role">${sellerMode?L('Selling mode','అమ్మకం మోడ్'):L('Buying mode','కొనుగోలు మోడ్')}</button></div><section class="hero"><div class="eyebrow">${L('GROW TOGETHER. TRADE BETTER.','కలిసి ఎదగండి. మంచి వ్యాపారం చేయండి.')}</div><h1>${sellerMode?L('Your next buyer is closer.','మీ తదుపరి కొనుగోలుదారు దగ్గరలోనే.'):L('From the farm.\nFor your business.','పొలం నుంచి మీ వ్యాపారానికి.')}</h1><p>${L('Discover harvests, livestock and local trade opportunities.','పంటలు, పశువులు మరియు స్థానిక వ్యాపార అవకాశాలను చూడండి.')}</p><div class="hero-bottom">${btn(sellerMode?L('Post a listing','లిస్టింగ్ పోస్ట్ చేయండి'):L('Explore market','మార్కెట్ చూడండి'),sellerMode?'start-sell':'browse','','')}<button class="link" data-action="requests">${L('Buyer needs','కొనుగోలుదారుల అవసరాలు')} →</button></div></section><form data-form="search" class="search">${icon('search')}<input name="query" placeholder="${L('Search paddy, buffaloes, fish…','వరి, గేదెలు, చేపలు వెతకండి…')}" aria-label="Search marketplace"><button type="submit" aria-label="Search">${icon('chevron')}</button></form><div class="section-head"><h2>${L('Shop by category','వర్గం ప్రకారం చూడండి')}</h2><small class="muted">8 ${L('segments','వర్గాలు')}</small></div><div class="categories">${MD.categories.map(c=>`<button class="category" data-action="category" data-id="${c.id}"><div class="category-art"><img src="art/${c.image}.svg" alt=""></div><span>${L(c.name,c.te)}</span></button>`).join('')}</div><div class="section-head"><h2>${L('Featured farm listings','ప్రత్యేక ఫార్మ్ లిస్టింగ్‌లు')}</h2><button class="link" data-action="browse">${L('View all','అన్నీ చూడండి')} →</button></div><div class="grid">${['L101','L109','L112','L115'].map(id=>getListing(id)).filter(available).map(card).join('')}</div><button class="banner" data-action="requests" style="width:100%;text-align:left"><span class="circle">${icon('request')}</span><div style="flex:1"><h3>${L('Buyers are looking for your stock','మీ సరుకు కోసం కొనుగోలుదారులు చూస్తున్నారు')}</h3><p>${L('See requirements and send a quote.','అవసరాలు చూసి ధర ప్రతిపాదన పంపండి.')}</p></div>${icon('chevron')}</button><div class="section-head"><h2>${L('Trade with more clarity','స్పష్టమైన వ్యాపారం')}</h2></div><div class="card"><div class="person"><div class="avatar">${icon('shield')}</div><div class="info"><h3>${L('Know what was checked','ఏది తనిఖీ చేశారో తెలుసుకోండి')}</h3><p>${L('Identity, quality and health are separate checks.','గుర్తింపు, నాణ్యత మరియు ఆరోగ్యం వేర్వేరు తనిఖీలు.')}</p></div></div><div class="inline-actions"><button data-action="services">${L('Inspection services','తనిఖీ సేవలు')}</button><button data-action="help">${L('How trading works','వ్యాపారం ఎలా జరుగుతుంది')}</button></div></div>`, 'home',true);}
function browse(){const rows=filtered();return shell(L('Explore marketplace','మార్కెట్ చూడండి'),`<div class="row"><div><h1>${ui.filters.cat==='all'?L('Find your next lot','మీ తదుపరి సరుకు చూడండి'):L(cat(ui.filters.cat).name,cat(ui.filters.cat).te)}</h1><p class="muted small spaced" id="result-count">${rows.length} ${L('available demo listings','లభ్యమైన నమూనా లిస్టింగ్‌లు')}</p></div><button class="icon-button" data-action="filters" aria-label="${L('Filters','ఫిల్టర్లు')}">${icon('filter')}</button></div><div class="search">${icon('search')}<input id="browse-search" value="${esc(ui.filters.query)}" placeholder="${L('Search title or location','పేరు లేదా ప్రాంతం వెతకండి')}" aria-label="Search listings"></div>${categoryChips()}<div id="browse-results">${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:empty(L('No matching listings','సరిపోలే లిస్టింగ్‌లు లేవు'),L('Change the category, price or location filters.','వర్గం, ధర లేదా ప్రాంతం ఫిల్టర్లు మార్చండి.'),btn(L('Clear filters','ఫిల్టర్లు తొలగించండి'),'clear-filters'))}</div>`,'home');}
function detail(){const p=getListing(ui.params.id);if(!p)return shell(L('Listing','లిస్టింగ్'),empty(L('Listing unavailable','లిస్టింగ్ లభ్యం లేదు'),L('Return to the marketplace.','మార్కెట్‌కు తిరిగి వెళ్లండి.')));const s=seller(p.seller),animal=['cattle','smallstock','poultry'].includes(p.cat);return shell(L('Listing details','లిస్టింగ్ వివరాలు'),`<div class="detail-art"><img src="art/${p.image}.svg" alt="${esc(title(p))}"><small>${L('Demo illustration','నమూనా చిత్రం')}</small></div><div class="row"><span class="tag">${L(cat(p.cat).name,cat(p.cat).te)}</span><button class="icon-button" data-action="save-listing" data-id="${p.id}" aria-label="Save listing">${icon('heart')}</button></div><h1 class="spaced">${esc(title(p))}</h1><div class="detail-price">${money(p.price)} <small>/ ${unit(p.unit)}</small></div><div class="meta">${esc(p.location)} · ${p.distance} ${L('km demo distance','కి.మీ నమూనా దూరం')}</div><div class="specs"><div><small>${L('Available quantity','లభ్య పరిమాణం')}</small><strong>${p.quantity.toLocaleString('en-IN')} ${unit(p.unit)}</strong></div><div><small>${L('Minimum order','కనీస ఆర్డర్')}</small><strong>${p.min} ${unit(p.unit)}</strong></div><div><small>${L('Listing expires','లిస్టింగ్ గడువు')}</small><strong>${p.expires}</strong></div><div><small>${L('Availability','లభ్యత')}</small><strong>${available(p)?L('Available','లభ్యం'):esc(p.status)}</strong></div></div><div class="section-head"><h2>${L('Lot information','సరుకు సమాచారం')}</h2></div><div class="card"><div class="specs">${p.specs.map(([k,v])=>`<div><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div></div><div class="card"><h3>${L('Checks and documents','తనిఖీలు మరియు పత్రాలు')}</h3><div class="invoice-row"><span>${L('Seller identity','విక్రేత గుర్తింపు')}</span><strong>${p.identity==='sample'?L('Sample identity badge','నమూనా గుర్తింపు బ్యాడ్జ్'):L('Not checked','తనిఖీ చేయలేదు')}</strong></div><div class="invoice-row"><span>${animal?L('Animal health','జంతువు ఆరోగ్యం'):L('Product quality','ఉత్పత్తి నాణ్యత')}</span><strong>${['samplelab','samplevet'].includes(p.quality)?L('Sample report only','నమూనా రిపోర్ట్ మాత్రమే'):L('Seller declaration','విక్రేత ప్రకటన')}</strong></div>${['samplelab','samplevet'].includes(p.quality)?`<button class="link spaced" data-action="listing-report" data-id="${p.id}">${L('Open sample report','నమూనా రిపోర్ట్ చూడండి')} →</button>`:''}${note('These badges do not verify a real person, product or animal. Arrange physical checks before an actual purchase.','ఈ బ్యాడ్జ్‌లు నిజమైన వ్యక్తి, సరుకు లేదా జంతువును ధృవీకరించవు. నిజమైన కొనుగోలు ముందు ప్రత్యక్ష తనిఖీ చేయించండి.')}</div><div class="card"><div class="person"><div class="avatar">${esc(s.initials)}</div><div class="info"><h3>${esc(L(s.name,s.te))}</h3><p>${esc(s.type)} · ${esc(s.location)}</p></div></div><div class="inline-actions"><button data-action="chat-listing" data-id="${p.id}">${L('Message seller','విక్రేతకు సందేశం')}</button><button data-action="call-demo" data-id="${p.id}">${L('Call preview','కాల్ నమూనా')}</button><button data-action="share-listing" data-id="${p.id}">${L('Share details','వివరాలు పంచుకోండి')}</button></div></div><div class="card"><h3>${L('Seller description','విక్రేత వివరణ')}</h3><p class="muted small">${esc(p.description)}</p></div><button class="link" data-action="report-listing" data-id="${p.id}">${L('Report this listing','ఈ లిస్టింగ్‌పై ఫిర్యాదు')}</button>`,'',false,'',`<div class="sticky-actions">${btn(icon('chat')+L('Enquire','విచారించండి'),'chat-listing',p.id,'secondary')}${btn(L('Make an offer','ధర ప్రతిపాదన'),'offer',p.id,available(p)?'':'secondary')}</div>`);}
function welcome(){return `<main class="welcome"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div class="brandname">Agromitra<span>MARKET</span></div></div><img class="welcome-art" src="art/landscape.svg" alt="Illustrated farmland"><div class="eyebrow" style="color:var(--forest)">${L('FARM TO MARKET','పొలం నుంచి మార్కెట్‌కు')}</div><h1>${L('A better place to buy.\nA simpler way to sell.','కొనడానికి మంచి వేదిక.\nఅమ్మడానికి సులభమైన మార్గం.')}</h1><p class="lead">${L('Explore crops, livestock, poultry and aquaculture. Try every trade flow with local sample data.','పంటలు, పశువులు, కోళ్లు మరియు ఆక్వాకల్చర్ చూడండి. నమూనా డేటాతో ప్రతి ప్రక్రియను ప్రయత్నించండి.')}</p><div class="language-options"><button data-action="language" data-id="en" class="${state.profile.language==='en'?'active':''}">English</button><button data-action="language" data-id="te" class="${state.profile.language==='te'?'active':''}">తెలుగు</button></div>${btn(L('Start prototype','నమూనా ప్రారంభించండి'),'onboard')}${note('No real login, payment or booking. Your changes are saved on this device.','నిజమైన లాగిన్, చెల్లింపు లేదా బుకింగ్ లేదు. మార్పులు ఈ పరికరంలో సేవ్ అవుతాయి.')}</main>`;}
function onboard(){return shell(L('Set up demo profile','నమూనా ప్రొఫైల్'),`<h1>${L('How will you trade?','మీరు ఎలా వ్యాపారం చేస్తారు?')}</h1><p class="lead">${L('You can switch between buying and selling later.','తరువాత కొనుగోలు, అమ్మకం మోడ్‌లు మార్చవచ్చు.')}</p><form data-form="onboard">${field(L('Your name or farm name','మీ పేరు లేదా ఫార్మ్ పేరు'),'name',state.profile.name,'text','required maxlength="60"')}${select(L('Start as','ప్రారంభ మోడ్'),'role',[['buyer',L('Buyer','కొనుగోలుదారు')],['seller',L('Seller / farmer','విక్రేత / రైతు')]],state.profile.role)}${select(L('Business type','వ్యాపార రకం'),'business',['Individual','Farmer','FPO','Trader','Miller','Processor','Dairy farmer','Poultry farmer','Aqua farmer'],state.profile.business)}${select(L('Demo location','నమూనా ప్రాంతం'),'city',['Guntur','Mangalagiri','Vijayawada','Tenali','Ongole','Nellore','Nuzvid','Bhimavaram','Khammam'],state.profile.city)}<label class="check"><input type="checkbox" name="agree" required><span>${L('I understand this is an offline prototype with fictional sample data.','ఇది కల్పిత నమూనా డేటాతో ఉన్న ఆఫ్‌లైన్ నమూనా అని అర్థం చేసుకున్నాను.')}</span></label>${errorBox()}${submit(L('Enter marketplace','మార్కెట్‌లోకి వెళ్ళండి'))}</form>`);}
function savedPage(){const rows=state.listings.filter(p=>state.saved.includes(p.id));return shell(L('Saved listings','సేవ్ చేసిన లిస్టింగ్‌లు'),`<h1>${L('Your shortlist','మీ ఎంపికలు')}</h1><p class="lead">${L('Keep useful listings together before you enquire.','విచారించే ముందు ఉపయోగకరమైన లిస్టింగ్‌లు సేవ్ చేసుకోండి.')}</p>${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:empty(L('Nothing saved yet','ఇంకా సేవ్ చేయలేదు'),L('Tap the heart on a listing to save it.','లిస్టింగ్‌పై హృదయం గుర్తును నొక్కండి.'),btn(L('Explore listings','లిస్టింగ్‌లు చూడండి'),'browse'))}`,'account');}
function requestCard(r){return `<article class="request-card"><div class="row"><span class="tag">${L(cat(r.cat).name,cat(r.cat).te)}</span><small class="muted">${r.own?L('Your request','మీ అవసరం'):L('Demo buyer','నమూనా కొనుగోలుదారు')}</small></div><h3>${esc(title(r))}</h3><p class="small muted">${esc(r.buyer)} · ${esc(r.location)}</p><div class="request-stats"><strong>${r.quantity.toLocaleString('en-IN')} ${unit(r.unit)}</strong><span>${L('Budget up to','బడ్జెట్ గరిష్ఠంగా')} ${money(r.budget)}/${unit(r.unit)}</span><span>${L('Until','గడువు')} ${r.expires}</span></div>${btn(L('View requirement','అవసరం చూడండి'),'request-detail',r.id,'secondary')}</article>`;}
function requestsPage(){const rs=state.requests.filter(r=>r.status==='open'&&r.expires>=today()&&(ui.requestCat==='all'||r.cat===ui.requestCat)&&(ui.requestTab!=='mine'||r.own));return shell(L('Buyer requirements','కొనుగోలుదారుల అవసరాలు'),`<h1>${L('Demand meets supply.','అవసరం, సరుకు కలుస్తాయి.')}</h1><p class="lead">${L('Buyers post requirements. Farmers and suppliers respond with quotes.','కొనుగోలుదారులు అవసరాలు పోస్ట్ చేస్తారు. రైతులు మరియు సరఫరాదారులు ధర ప్రతిపాదనలు పంపుతారు.')}</p>${btn(icon('plus')+L('Post a buyer requirement','కొనుగోలుదారు అవసరం పోస్ట్ చేయండి'),'new-request')}<div class="chips spaced"><button class="chip ${ui.requestTab==='all'?'active':''}" data-action="request-tab" data-id="all">${L('All requests','అన్ని అవసరాలు')}</button><button class="chip ${ui.requestTab==='mine'?'active':''}" data-action="request-tab" data-id="mine">${L('My requests','నా అవసరాలు')}</button></div>${categoryChips('request-cat',ui.requestCat)}${rs.length?rs.map(requestCard).join(''):empty(L('No open requirements here','ఇక్కడ అవసరాలు లేవు'),L('Post a requirement or choose another category.','అవసరం పోస్ట్ చేయండి లేదా వేరే వర్గం ఎంచుకోండి.'))}`,'requests');}
function requestDetail(){const r=getRequest(ui.params.id);if(!r)return shell('Request',empty('Unavailable','Return to requests.'));const deals=state.deals.filter(d=>d.requestId===r.id);return shell(L('Requirement details','అవసరం వివరాలు'),`<span class="tag">${L(cat(r.cat).name,cat(r.cat).te)}</span><h1 class="spaced">${esc(title(r))}</h1><p class="lead">${esc(r.buyer)} · ${esc(r.location)}</p><div class="card"><div class="invoice-row"><span>${L('Quantity required','అవసరమైన పరిమాణం')}</span><strong>${r.quantity.toLocaleString('en-IN')} ${unit(r.unit)}</strong></div><div class="invoice-row"><span>${L('Budget per unit','యూనిట్ బడ్జెట్')}</span><strong>${money(r.budget)} / ${unit(r.unit)}</strong></div><div class="invoice-row"><span>${L('Purpose','ప్రయోజనం')}</span><strong>${esc(r.purpose)}</strong></div><div class="invoice-row"><span>${L('Required before','గడువు')}</span><strong>${r.expires}</strong></div><p class="small muted spaced">${esc(r.note)}</p></div>${note('The buyer and requirement are demo data. Quotes remain on this device.','కొనుగోలుదారు మరియు అవసరం నమూనా డేటా. ప్రతిపాదనలు ఈ పరికరంలోనే ఉంటాయి.')}${r.own?btn(L('Generate a sample supplier quote','నమూనా సరఫరాదారు ప్రతిపాదన'),'sample-rfq-quote',r.id):btn(L('Respond with a quote','ధర ప్రతిపాదన పంపండి'),'rfq-quote',r.id)}<div class="section-head"><h2>${L('Quotes received / sent','అందిన / పంపిన ప్రతిపాదనలు')}</h2><small>${deals.length}</small></div>${deals.length?deals.map(dealCard).join(''):empty(L('No quotes yet','ఇంకా ప్రతిపాదనలు లేవు'),L('Try a supplier quote to continue the trade flow.','వ్యాపార ప్రక్రియ కొనసాగించడానికి ప్రతిపాదన ప్రయత్నించండి.'))}${r.own?btn(L('Close requirement','అవసరం మూసివేయండి'),'close-request',r.id,'secondary'):''}`,'requests');}
function requestForm(){const d=ui.requestDraft||{cat:'crops',title:'',quantity:'',unit:'quintal',budget:'',location:state.profile.city,purpose:'Commercial sourcing',note:'',expires:future(7)};return shell(L('Post requirement','అవసరం పోస్ట్ చేయండి'),`<h1>${L('Tell sellers what you need','మీ అవసరం విక్రేతలకు చెప్పండి')}</h1><p class="lead">${L('Clear quantity, quality and pickup terms help sellers quote.','పరిమాణం, నాణ్యత మరియు పికప్ నిబంధనలు స్పష్టంగా చెప్పండి.')}</p><button class="link" data-action="fill-request">${L('Fill a sample requirement','నమూనా అవసరం నింపండి')}</button><form data-form="request">${select(L('Category','వర్గం'),'cat',MD.categories.map(c=>[c.id,L(c.name,c.te)]),d.cat)}${field(L('Requirement title','అవసరం పేరు'),'title',d.title,'text','required minlength="3" maxlength="90"')}<div class="fields-2">${field(L('Quantity','పరిమాణం'),'quantity',d.quantity,'number','required min="0.01" step="0.01"')}${select(L('Unit','యూనిట్'),'unit',['quintal','kg','animal','bird','egg','litre','fish'].map(u=>[u,unit(u)]),d.unit)}</div>${field(L('Maximum budget per unit (₹)','యూనిట్‌కు గరిష్ఠ బడ్జెట్ (₹)'),'budget',d.budget,'number','required min="0.01" step="0.01"')}${field(L('Location','ప్రాంతం'),'location',d.location,'text','required maxlength="70"')}${select(L('Purpose','ప్రయోజనం'),'purpose',['Commercial sourcing','Milling','Dairy farming','Rearing','Wholesale','Distribution','Dairy collection'],d.purpose)}${field(L('Requirement expires','అవసరం గడువు'),'expires',d.expires,'date',`required min="${today()}"`)}${textarea(L('Quality, inspection and pickup requirements','నాణ్యత, తనిఖీ మరియు పికప్ అవసరాలు'),'note',d.note,'required maxlength="800"')}${errorBox()}${submit(L('Publish demo requirement','నమూనా అవసరం ప్రచురించండి'))}</form>`,'requests');}
function offerForm(){const p=getListing(ui.params.id),r=getRequest(ui.params.requestId),rfq=!!r;if(!p&&!r)return shell('Offer','');const item=p||{title:r.title,te:r.te,unit:r.unit,price:r.budget,min:1,quantity:r.quantity};return shell(rfq?L('Supplier quote','సరఫరాదారు ప్రతిపాదన'):L('Make an offer','ధర ప్రతిపాదన'),`<h1>${rfq?L('Quote your supply','మీ సరుకు ధర చెప్పండి'):L('Start the conversation','చర్చ ప్రారంభించండి')}</h1><p class="lead">${esc(title(item))}</p><form data-form="offer" data-id="${p?p.id:''}" data-request-id="${r?r.id:''}"><div class="fields-2">${field(L('Quantity','పరిమాణం')+' ('+unit(item.unit)+')','quantity',p?item.min:r.quantity,'number',`required min="${p?p.min:1}" ${p?`max="${p.quantity}"`:''} step="${['animal','bird','egg','fish'].includes(item.unit)?'1':'0.01'}"`)}${field(L('Your price per unit (₹)','మీ యూనిట్ ధర (₹)'),'price',item.price,'number','required min="0.01" step="0.01"')}</div>${field(L('Pickup / delivery location','పికప్ / డెలివరీ ప్రాంతం'),'location',state.profile.city,'text','required maxlength="70"')}${field(L('Preferred date','కావలసిన తేదీ'),'date',future(2),'date',`required min="${today()}"`)}${textarea(L('Message and conditions','సందేశం మరియు నిబంధనలు'),'message',L('I would like to inspect before final confirmation. Please confirm availability.','తుది నిర్ధారణ ముందు తనిఖీ చేయాలనుకుంటున్నాను. లభ్యత నిర్ధారించండి.'),'required maxlength="800"')}<div class="notice" id="offer-total">${L('Indicative lot value','అంచనా సరుకు విలువ')}: ${money((p?p.min:r.quantity)*item.price)}</div>${note('This sends a local demo offer. No seller is contacted and no payment is made.','ఇది స్థానిక నమూనా ప్రతిపాదన. నిజమైన విక్రేతను సంప్రదించరు, చెల్లింపు జరగదు.',true)}${errorBox()}${submit(rfq?L('Send sample quote','నమూనా ప్రతిపాదన పంపండి'):L('Send sample offer','నమూనా ధర ప్రతిపాదన పంపండి'))}</form>`);}
const DETAIL_FIELDS={crops:[['Variety','రకం'],['Harvest / availability','పంట / లభ్యత'],['Moisture / grade (declared)','తేమ / గ్రేడ్ (విక్రేత ప్రకటన)'],['Packing','ప్యాకింగ్']],produce:[['Variety','రకం'],['Harvest / ripeness','కోత / పక్వత'],['Sorting grade (declared)','నాణ్యత గ్రేడ్ (విక్రేత ప్రకటన)'],['Packing / pickup window','ప్యాకింగ్ / పికప్ సమయం']],cattle:[['Breed','జాతి'],['Age / lactation (declared)','వయసు / ఈత (విక్రేత ప్రకటన)'],['Milk yield / purpose (declared)','పాల దిగుబడి / ప్రయోజనం'],['Health / vaccination records','ఆరోగ్య / టీకా పత్రాలు']],smallstock:[['Breed','జాతి'],['Age range (declared)','వయసు (విక్రేత ప్రకటన)'],['Average weight (declared)','సగటు బరువు (విక్రేత ప్రకటన)'],['Health / vaccination records','ఆరోగ్య / టీకా పత్రాలు']],poultry:[['Broiler / layer / desi / chicks','బ్రాయిలర్ / లేయర్ / దేశీ / పిల్లలు'],['Age and bird count','వయసు మరియు కోళ్ల సంఖ్య'],['Average weight (declared)','సగటు బరువు (విక్రేత ప్రకటన)'],['Flock records / pickup','బ్యాచ్ పత్రాలు / పికప్']],eggs:[['Table / hatching eggs','తినే / పొదిగే గుడ్లు'],['Collection date','సేకరణ తేదీ'],['Grade (declared)','గ్రేడ్ (విక్రేత ప్రకటన)'],['Tray packing / breakage terms','ట్రే ప్యాకింగ్ / పగుళ్ల నిబంధనలు']],aqua:[['Species / seed type','జాతి / పిల్లల రకం'],['Size / count (declared)','పరిమాణం / కౌంట్'],['Harvest / availability','కోత / లభ్యత'],['Handling / temperature needs','రవాణా / ఉష్ణోగ్రత అవసరాలు']],dairy:[['Milk type / product','పాల రకం / ఉత్పత్తి'],['Collection timing','సేకరణ సమయం'],['Fat / SNF (declared)','ఫ్యాట్ / ఎస్ఎన్ఎఫ్'],['Handling / temperature needs','నిల్వ / ఉష్ణోగ్రత అవసరాలు']]};
function newDraft(category='crops'){return {cat:category,title:'',price:'',quantity:'',min:'',unit:cat(category).unit,image:cat(category).image,location:state.profile.city,state:'Andhra Pradesh',description:'',specValues:['','','',''],expires:future(14)};}
function captureDraft(){const f=document.querySelector('form[data-form="sell-basic"],form[data-form="sell-details"]');if(!f||!ui.draft)return;const o=Object.fromEntries(new FormData(f));if(f.dataset.form==='sell-basic'){for(const k of ['title','price','quantity','min','unit','location','state','expires'])if(o[k]!=null)ui.draft[k]=o[k];}else{ui.draft.specValues=[0,1,2,3].map(i=>o['spec'+i]||'');ui.draft.description=o.description||'';}}
function sellPage(){const step=Number(ui.params.step||1);if(!ui.draft)ui.draft=newDraft();const d=ui.draft,c=cat(d.cat);let body=`<div class="step-label">${L('STEP','దశ')} ${step} / 4</div><div class="wizard-progress">${[1,2,3,4].map(x=>`<i class="${x<=step?'on':''}"></i>`).join('')}</div>`;
 if(step===1)body+=`<h1>${L('What are you selling?','మీరు ఏమి అమ్ముతున్నారు?')}</h1><p class="lead">${L('Choose a segment. Each has its own listing details.','వర్గం ఎంచుకోండి. ప్రతి వర్గానికి ప్రత్యేక వివరాలు ఉంటాయి.')}</p>${btn(icon('mic')+L('Try voice listing demo','వాయిస్ లిస్టింగ్ నమూనా'),'voice-listing','','secondary')}<div class="spaced">${MD.categories.map(c=>`<button class="option" data-action="sell-category" data-id="${c.id}"><img src="art/${c.image}.svg" alt=""><div><strong>${L(c.name,c.te)}</strong><p>${L(c.help,c.helpTe)}</p></div>${icon('chevron')}</button>`).join('')}</div>`;
 if(step===2)body+=`<h1>${L('Create your listing','మీ లిస్టింగ్ సృష్టించండి')}</h1><p class="lead">${L(c.name,c.te)} · ${L('Price and quantity use the same unit.','ధర మరియు పరిమాణం ఒకే యూనిట్‌లో ఉండాలి.')}</p><button class="link" data-action="fill-sell">${L('Fill sample details','నమూనా వివరాలు నింపండి')}</button><form data-form="sell-basic">${field(L('Listing title','లిస్టింగ్ పేరు'),'title',d.title,'text','required minlength="3" maxlength="90"')}<div class="fields-2">${field(L('Quantity available','లభ్య పరిమాణం'),'quantity',d.quantity,'number','required min="0.01" max="10000000" step="0.01"')}${select(L('Unit','యూనిట్'),'unit',['quintal','kg','animal','bird','egg','litre','fish'].map(u=>[u,unit(u)]),d.unit)}</div><div class="fields-2">${field(L('Price per unit (₹)','యూనిట్ ధర (₹)'),'price',d.price,'number','required min="0.01" max="100000000" step="0.01"')}${field(L('Minimum order','కనీస ఆర్డర్'),'min',d.min,'number','required min="0.01" step="0.01"')}</div>${field(L('Location','ప్రాంతం'),'location',d.location,'text','required maxlength="70"')}${select(L('State','రాష్ట్రం'),'state',['Andhra Pradesh','Telangana','Other'],d.state)}${field(L('Listing expiry date','లిస్టింగ్ గడువు'),'expires',d.expires,'date',`required min="${today()}"`)}<label class="field"><span>${L('Listing image','లిస్టింగ్ చిత్రం')}</span><button type="button" class="option" data-action="photos"><img src="art/${d.image}.svg" alt=""><div><strong>${L('Choose a demo illustration','నమూనా చిత్రం ఎంచుకోండి')}</strong><p>${L('Sample photo selection flow','నమూనా ఫోటో ఎంపిక ప్రక్రియ')}</p></div>${icon('camera')}</button></label>${errorBox()}${submit(L('Continue to details','వివరాలకు కొనసాగండి'))}</form>`;
 if(step===3)body+=`<h1>${L('Help buyers decide','కొనుగోలుదారులకు వివరాలు ఇవ్వండి')}</h1><p class="lead">${L('These details remain seller declarations until checked.','తనిఖీ చేసే వరకు ఇవి విక్రేత ప్రకటనలుగానే ఉంటాయి.')}</p><form data-form="sell-details">${DETAIL_FIELDS[d.cat].map((k,i)=>field(L(k[0],k[1]),'spec'+i,d.specValues[i]||'','text','required maxlength="100"')).join('')}${textarea(L('Description and pickup conditions','వివరణ మరియు పికప్ నిబంధనలు'),'description',d.description,'required minlength="10" maxlength="1200"')}${note('Health, milk yield, crop grade and weights cannot be verified from a listing illustration.','ఆరోగ్యం, పాల దిగుబడి, పంట గ్రేడ్ మరియు బరువును లిస్టింగ్ చిత్రం ద్వారా ధృవీకరించలేరు.')}${errorBox()}${submit(L('Preview listing','లిస్టింగ్ ప్రివ్యూ'))}</form>`;
 if(step===4)body+=`<h1>${L('Review before publishing','ప్రచురించే ముందు చూడండి')}</h1><p class="lead">${L('Your demo listing will appear in the public marketplace view on this device.','మీ నమూనా లిస్టింగ్ ఈ పరికరంలోని మార్కెట్‌లో కనిపిస్తుంది.')}</p><div class="card" style="padding:0;overflow:hidden"><div class="product-media" style="height:200px"><img src="art/${d.image}.svg" alt=""><span class="art-credit">Illustration</span></div><div style="padding:18px"><h2>${esc(d.title)}</h2><div class="detail-price">${money(d.price)} <small>/ ${unit(d.unit)}</small></div><p class="meta">${d.quantity} ${unit(d.unit)} · ${esc(d.location)}</p><div class="specs">${DETAIL_FIELDS[d.cat].map((k,i)=>`<div><small>${L(k[0],k[1])}</small><strong>${esc(d.specValues[i])}</strong></div>`).join('')}</div><p class="small muted spaced">${esc(d.description)}</p></div></div><form data-form="sell-publish"><label class="check"><input name="confirmed" type="checkbox" required><span>${L('I confirm these demo details and understand that real sellers must provide accurate information and applicable documents.','ఈ నమూనా వివరాలు నిర్ధారిస్తున్నాను. నిజమైన విక్రేతలు సరైన సమాచారం మరియు అవసరమైన పత్రాలు ఇవ్వాలి.')}</span></label>${errorBox()}${submit(d.editId?L('Save listing changes','లిస్టింగ్ మార్పులు సేవ్ చేయండి'):L('Publish demo listing','నమూనా లిస్టింగ్ ప్రచురించండి'))}</form>${btn(L('Edit details','వివరాలు మార్చండి'),'sell-step','2','secondary spaced')}`;
 return shell(L('Sell on Agromitra','ఆగ్రోమిత్రలో అమ్మండి'),body,'sell');}
function manageListings(){const rows=state.listings.filter(p=>p.own);return shell(L('My listings','నా లిస్టింగ్‌లు'),`<h1>${L('Manage your stock','మీ సరుకు నిర్వహించండి')}</h1><p class="lead">${L('Edit, pause, mark sold or renew your listings.','లిస్టింగ్ మార్చండి, నిలిపివేయండి, అమ్మినట్లు గుర్తించండి లేదా గడువు పొడిగించండి.')}</p>${btn(icon('plus')+L('Add a listing','లిస్టింగ్ జోడించండి'),'start-sell')}<div class="spaced">${rows.length?rows.map(p=>`<div class="deal-card"><div class="row"><img class="thumb" src="art/${p.image}.svg" alt=""><div style="flex:1"><h3>${esc(title(p))}</h3><p>${money(p.price)}/${unit(p.unit)} · ${p.quantity} ${unit(p.unit)}</p><span class="tag ${p.status==='sold'?'gold':''}">${p.expires<today()?L('Expired','గడువు ముగిసింది'):esc(p.status)}</span></div></div><div class="inline-actions"><button data-action="edit-listing" data-id="${p.id}">${L('Edit','మార్చండి')}</button><button data-action="toggle-listing" data-id="${p.id}">${p.status==='active'?L('Pause','నిలిపివేయండి'):L('Activate','ప్రారంభించండి')}</button><button data-action="sold-listing" data-id="${p.id}">${L('Mark sold','అమ్మినట్లు గుర్తించండి')}</button><button data-action="renew-listing" data-id="${p.id}">${L('Renew 14 days','14 రోజులు పొడిగించండి')}</button></div></div>`).join(''):empty(L('Create your first listing','మీ తొలి లిస్టింగ్ సృష్టించండి'),L('Use sample details to try the full selling flow.','పూర్తి అమ్మకం ప్రక్రియ కోసం నమూనా వివరాలు ఉపయోగించండి.'))}</div>`,'account');}
const STAGES=['quote','inspection','agreement','payment','transport','delivery','complete'];
const stageLabel=(s)=>L(({quote:'Quote / negotiation',inspection:'Inspection / visit',agreement:'Agree trade terms',payment:'Payment arrangement',transport:'Book transport',delivery:'Pickup and delivery',complete:'Completed',cancelled:'Cancelled / refunded'})[s],({quote:'ధర చర్చ',inspection:'తనిఖీ / సందర్శన',agreement:'వ్యాపార నిబంధనలు',payment:'చెల్లింపు ఏర్పాటు',transport:'రవాణా బుకింగ్',delivery:'పికప్ మరియు డెలివరీ',complete:'పూర్తయింది',cancelled:'రద్దు / తిరిగి చెల్లింపు'})[s]);
function dealCard(d){return `<article class="deal-card"><div class="row"><img class="thumb" src="art/${d.image}.svg" alt=""><div style="flex:1"><h3>${esc(d.title)}</h3><p>${d.quantity} ${unit(d.unit)} · ${money(dealTotal(d))}</p><p>${money(d.price)} / ${unit(d.unit)}</p><p>${esc(d.seller)} → ${esc(d.buyer)}</p></div></div><span class="tag ${d.stage==='complete'?'gold':''}">${d.disputed?L('Dispute open','వివాదం కొనసాగుతోంది'):stageLabel(d.stage)}</span>${btn(L('Open deal','ఒప్పందం చూడండి'),'deal',d.id,'secondary')}</article>`;}
function dealsPage(){const rows=state.deals.filter(d=>ui.dealTab==='complete'?['complete','cancelled'].includes(d.stage):ui.dealTab==='all'?true:!['complete','cancelled'].includes(d.stage));return shell(L('Trade workspace','వ్యాపార నిర్వహణ'),`<h1>${L('Every step, in one place.','ప్రతి దశ ఒకే చోట.')}</h1><p class="lead">${L('Quotes, inspections, terms, payments and delivery.','ధర ప్రతిపాదనలు, తనిఖీలు, నిబంధనలు, చెల్లింపులు మరియు డెలివరీ.')}</p><div class="chips">${[['active',L('Active','కొనసాగుతున్నవి')],['complete',L('Completed','పూర్తయినవి')],['all',L('All','అన్నీ')]].map(([v,t])=>`<button class="chip ${ui.dealTab===v?'active':''}" data-action="deal-tab" data-id="${v}">${t}</button>`).join('')}</div>${rows.length?rows.map(dealCard).join(''):empty(L('No deals in this view','ఇక్కడ ఒప్పందాలు లేవు'),L('Make an offer or respond to a buyer requirement.','ధర ప్రతిపాదన పంపండి లేదా కొనుగోలుదారు అవసరానికి స్పందించండి.'),btn(L('Browse market','మార్కెట్ చూడండి'),'browse'))}`,'deals');}
function dealPage(){const d=getDeal(ui.params.id);if(!d)return shell('Deal',empty('Deal unavailable','Return to Deals.'));const idx=d.stage==='cancelled'?-1:STAGES.indexOf(d.stage);let action='';
 if(d.stage==='quote')action=btn(L('Receive demo acceptance','నమూనా అంగీకారం పొందండి'),'accept-quote',d.id)+`<div class="btn-row">${btn(L('Try a counteroffer','మారుప్రతిపాదన ప్రయత్నించండి'),'counteroffer',d.id,'secondary')}${btn(L('Open chat','చాట్ చూడండి'),'chat-deal',d.id,'secondary')}</div>`;
 if(d.stage==='inspection')action=d.inspection&&d.inspection.status==='Scheduled'?btn(L('Record sample inspection results','నమూనా తనిఖీ ఫలితాలు నమోదు చేయండి'),'inspection-results',d.id):btn(L('Arrange an inspection / visit','తనిఖీ / సందర్శన ఏర్పాటు'),'book-inspection',d.id)+`<button class="link spaced" data-action="skip-inspection" data-id="${d.id}">${L('Continue without inspection in demo','నమూనాలో తనిఖీ లేకుండా కొనసాగండి')} →</button>`;
 if(d.stage==='agreement')action=btn(L('Review and agree terms','నిబంధనలు చూసి అంగీకరించండి'),'agreement',d.id);
 if(d.stage==='payment')action=btn(L('Try demo advance payment','నమూనా అడ్వాన్స్ చెల్లింపు'),'payment',d.id)+`<button class="link spaced" data-action="pickup-payment" data-id="${d.id}">${L('Agree payment on pickup','పికప్ సమయంలో చెల్లింపు అంగీకరించండి')} →</button>`;
 if(d.stage==='transport')action=btn(L('Arrange transport','రవాణా ఏర్పాటు'),'transport',d.id);
 if(d.stage==='delivery')action=d.delivery&&d.delivery.phase==='In transit'?btn(L('Confirm receipt and settlement','స్వీకరణ మరియు చెల్లింపు నిర్ధారణ'),'receipt',d.id):btn(L('Record demo pickup','నమూనా పికప్ నమోదు చేయండి'),'pickup',d.id);
 if(d.stage==='complete')action=btn(L('View deal summary','ఒప్పంద సారాంశం చూడండి'),'deal-document',d.id)+`<div class="btn-row">${btn(L('Rate this demo trade','నమూనా వ్యాపారానికి రేటింగ్'),'rating',d.id,'secondary')}${btn(L('Trade again','మళ్లీ వ్యాపారం చేయండి'),'browse','','secondary')}</div>`;
 if(d.stage==='cancelled')action=btn(L('View cancellation summary','రద్దు సారాంశం చూడండి'),'deal-document',d.id,'secondary');
 return shell(L('Deal details','ఒప్పంద వివరాలు'),`<span class="tag">${L('DEMO DEAL','నమూనా ఒప్పందం')} · ${d.id}</span><h1 class="spaced">${esc(d.title)}</h1><p class="lead">${d.quantity} ${unit(d.unit)} · ${esc(d.location)}</p><div class="card"><div class="invoice-row"><span>${L('Product value','సరుకు విలువ')}</span><strong>${money(dealTotal(d))}</strong></div><div class="invoice-row"><span>${L('Demo advance recorded','నమూనా అడ్వాన్స్')}</span><strong>${money(paid(d))}</strong></div><div class="invoice-row"><span>${L('Product balance','సరుకు మిగిలిన మొత్తం')}</span><strong>${money(remaining(d))}</strong></div><div class="invoice-row"><span>${L('Buyer','కొనుగోలుదారు')}</span><strong>${esc(d.buyer)}</strong></div><div class="invoice-row"><span>${L('Seller','విక్రేత')}</span><strong>${esc(d.seller)}</strong></div></div>${d.disputed?`<div class="notice red">${L('A demo dispute is open. Resolve it in Support before completing this trade.','నమూనా వివాదం ఉంది. వ్యాపారం పూర్తి చేసే ముందు సపోర్ట్‌లో పరిష్కరించండి.')}</div>`:''}<div class="card"><h3>${L('Your next step','మీ తదుపరి దశ')}</h3><p class="small muted">${d.stage==='quote'?L('Use the sample seller response to try acceptance or negotiation.','అంగీకారం లేదా చర్చ కోసం నమూనా విక్రేత స్పందన ప్రయత్నించండి.'):stageLabel(d.stage)}</p><div class="spaced">${action}</div>${d.inspection?`<p class="small muted spaced">${L('Inspection','తనిఖీ')}: ${esc(d.inspection.provider)} · ${d.inspection.date} · ${esc(d.inspection.status)}</p>`:''}${d.delivery?`<p class="small muted spaced">${L('Transport','రవాణా')}: ${esc(d.delivery.partner)} · ${esc(d.delivery.phase)}</p>`:''}</div><div class="card"><h3>${L('Trade progress','వ్యాపార పురోగతి')}</h3><div class="timeline">${(d.stage==='cancelled'?[]:STAGES).map((s,i)=>`<div class="timeline-item ${i<idx?'done':i===idx?'current':''}"><div class="node">${i<idx?icon('check'):i+1}</div><div><strong>${stageLabel(s)}</strong><small>${i<idx?L('Recorded in prototype','నమూనాలో నమోదైంది'):i===idx?L('Current step','ప్రస్తుత దశ'):L('Upcoming','తదుపరి')}</small></div></div>`).join('')}</div></div>${state.ratings.filter(r=>r.dealId===d.id).map(r=>`<div class="card"><h3>${L('Your local demo review','మీ స్థానిక నమూనా సమీక్ష')}</h3><p style="color:var(--gold);font-size:22px">${'★'.repeat(r.stars)}</p><p class="small muted">${esc(r.review)}</p></div>`).join('')}<div class="card"><h3>${L('Documents and help','పత్రాలు మరియు సహాయం')}</h3><div class="inline-actions"><button data-action="deal-document" data-id="${d.id}">${L('Deal summary','ఒప్పంద సారాంశం')}</button>${d.inspection&&d.inspection.status==='Completed'?`<button data-action="inspection-document" data-id="${d.id}">${L('Inspection report','తనిఖీ రిపోర్ట్')}</button>`:''}<button data-action="chat-deal" data-id="${d.id}">${L('Chat','చాట్')}</button><button data-action="dispute" data-id="${d.id}">${L('Raise dispute','వివాదం నమోదు')}</button></div></div>${note('Payments, inspections and deliveries here are simulated. No funds, animals or goods move through this prototype.','ఇక్కడ చెల్లింపులు, తనిఖీలు మరియు డెలివరీలు నమూనాలు మాత్రమే. డబ్బు, జంతువులు లేదా సరుకు నిజంగా తరలించబడవు.')}`,'deals');}
function inspectionForm(){const d=getDeal(ui.params.id),animal=['cattle','smallstock','poultry'].includes(d.cat),provider=animal?'Sample veterinary team':d.cat==='aqua'?'Sample aqua inspection team':'Sample quality inspection team';return shell(L('Arrange inspection','తనిఖీ ఏర్పాటు'),`<h1>${animal?L('Check before you buy.','కొనుగోలు ముందు తనిఖీ.'):L('Agree quality with confidence.','నాణ్యత స్పష్టంగా తెలుసుకోండి.')}</h1><p class="lead">${esc(d.title)}</p><form data-form="inspection" data-id="${d.id}">${select(L('Service type','సేవ రకం'),'type',animal?['Farm visit + veterinary assessment','Farm visit only']:['Quality sample + lot inspection','Pickup site visit'],animal?'Farm visit + veterinary assessment':'Quality sample + lot inspection')}${select(L('Demo provider','నమూనా సేవాదారు'),'provider',[provider,provider+' B'],provider)}${field(L('Visit date','సందర్శన తేదీ'),'date',future(2),'date',`required min="${today()}"`)}${select(L('Time slot','సమయం'),'slot',['09:00–11:00','11:00–13:00','14:00–16:00'],'09:00–11:00')}${field(L('Farm / collection address','ఫార్మ్ / సేకరణ చిరునామా'),'address',d.location,'text','required maxlength="180"')}${textarea(L('What should be checked?','ఏవి తనిఖీ చేయాలి?'),'notes',animal?'Ownership records, animal identity, health, fitness and seller claims.':'Lot quantity, sample grade, packing, handling and agreed acceptance conditions.','required maxlength="600"')}<div class="card"><div class="invoice-row"><span>${L('Illustrative service fee','నమూనా సేవ రుసుము')}</span><strong>${money(animal?499:299)}</strong></div><small class="muted">${L('No fee is collected. This is a sample booking.','రుసుము వసూలు చేయరు. ఇది నమూనా బుకింగ్.')}</small></div>${errorBox()}${submit(L('Confirm demo booking','నమూనా బుకింగ్ నిర్ధారించండి'))}</form>`);}
function inspectionResults(){const d=getDeal(ui.params.id);return shell(L('Inspection results','తనిఖీ ఫలితాలు'),`<h1>${L('Record the sample visit','నమూనా సందర్శన నమోదు')}</h1><p class="lead">${L('These are simulated findings for demonstrating the report flow.','ఇవి రిపోర్ట్ ప్రక్రియ చూపడానికి నమూనా ఫలితాలు.')}</p><form data-form="inspection-results" data-id="${d.id}">${select(L('Demo outcome','నమూనా ఫలితం'),'outcome',['Acceptable in sample','Further checks needed'],'Acceptable in sample')}${textarea(L('Sample findings','నమూనా ఫలితాలు'),'findings',['cattle','smallstock','poultry'].includes(d.cat)?'Sample animal identity and records reviewed. Physical assessment is simulated. No real health or milk-yield certification is issued.':'Sample lot and packing reviewed. Quantity and grade are illustrative. No real quality certification is issued.','required maxlength="900"')}<label class="check"><input name="ack" type="checkbox" required><span>${L('I understand these results do not certify real goods or animals.','ఈ ఫలితాలు నిజమైన సరుకు లేదా జంతువులను ధృవీకరించవని అర్థమైంది.')}</span></label>${errorBox()}${submit(L('Save sample report','నమూనా రిపోర్ట్ సేవ్ చేయండి'))}</form>`);}
function agreementForm(){const d=getDeal(ui.params.id);return shell(L('Agree trade terms','వ్యాపార నిబంధనలు'),`<h1>${L('Put the agreement in writing.','నిబంధనలు రాతపూర్వకంగా నమోదు.')}</h1><p class="lead">${esc(d.title)} · ${money(dealTotal(d))}</p><form data-form="agreement" data-id="${d.id}">${select(L('Transport responsibility','రవాణా బాధ్యత'),'transport',['Buyer arranges','Seller arranges'],'Buyer arranges')}${select(L('Quantity / weight confirmation','పరిమాణం / బరువు నిర్ధారణ'),'weighment',['At farm pickup','At destination with agreed reconciliation'],'At farm pickup')}${textarea(L('Quality / health acceptance conditions','నాణ్యత / ఆరోగ్యం అంగీకార నిబంధనలు'),'quality','Buyer inspects the selected lot or animals. Seller declarations are checked before pickup. Any change must be agreed by both parties.','required maxlength="700"')}${textarea(L('Cancellation / rejection conditions','రద్దు / తిరస్కరణ నిబంధనలు'),'cancellation','If the lot differs from the written description, pause the trade and agree a resolution before loading. Demo advance records are reversible through a dispute resolution.','required maxlength="700"')}<label class="check"><input name="buyerAgree" type="checkbox" required><span>${L('Record demo buyer acceptance','నమూనా కొనుగోలుదారు అంగీకారం నమోదు')}</span></label><label class="check"><input name="sellerAgree" type="checkbox" required><span>${L('Record demo seller acceptance','నమూనా విక్రేత అంగీకారం నమోదు')}</span></label>${note('You are playing both sides of a sample transaction. This does not create a real sale agreement.','మీరు నమూనా లావాదేవీలో రెండు పాత్రలు పోషిస్తున్నారు. ఇది నిజమైన అమ్మకం ఒప్పందం కాదు.',true)}${errorBox()}${submit(L('Confirm demo terms','నమూనా నిబంధనలు నిర్ధారించండి'))}</form>`);}
function paymentForm(){const d=getDeal(ui.params.id),amount=Math.round(dealTotal(d)*.1*100)/100;return shell(L('Demo payment','నమూనా చెల్లింపు'),`<h1>${L('Try an advance payment.','అడ్వాన్స్ చెల్లింపు ప్రయత్నించండి.')}</h1><p class="lead">${L('This is a simulation. No payment app or bank is contacted.','ఇది నమూనా మాత్రమే. చెల్లింపు యాప్ లేదా బ్యాంకును సంప్రదించరు.')}</p><div class="card"><div class="invoice-row"><span>${L('Product value','సరుకు విలువ')}</span><strong>${money(dealTotal(d))}</strong></div><div class="invoice-row"><span>${L('10% demo advance','10% నమూనా అడ్వాన్స్')}</span><strong>${money(amount)}</strong></div><div class="invoice-row"><span>${L('Remaining product balance','మిగిలిన సరుకు మొత్తం')}</span><strong>${money(dealTotal(d)-amount)}</strong></div></div><form data-form="payment" data-id="${d.id}">${select(L('Payment method preview','చెల్లింపు విధానం నమూనా'),'method',['UPI simulation','Bank transfer simulation','Cash record simulation'],'UPI simulation')}<label class="check"><input name="ack" type="checkbox" required><span>${L('Record a fictional advance. No money will be deducted.','కల్పిత అడ్వాన్స్ నమోదు చేయండి. డబ్బు తీసివేయరు.')}</span></label>${errorBox()}${submit(L('Simulate advance payment','అడ్వాన్స్ చెల్లింపు నమూనా'))}</form>`);}
function transportForm(){const d=getDeal(ui.params.id),animal=['cattle','smallstock','poultry'].includes(d.cat),cold=['aqua','dairy','produce'].includes(d.cat);return shell(L('Arrange transport','రవాణా ఏర్పాటు'),`<h1>${L('Plan a suitable pickup.','తగిన పికప్ ఏర్పాటు.')}</h1><p class="lead">${L('The route and handling depend on what you are buying.','మీరు కొనుగోలు చేసే సరుకు ఆధారంగా రవాణా అవసరాలు మారుతాయి.')}</p><form data-form="transport" data-id="${d.id}">${select(L('Demo transport partner','నమూనా రవాణాదారు'),'partner',animal?['Sample livestock carrier','Sample farm transport']:cold?['Sample temperature-controlled carrier','Sample suitable collection vehicle']:['Sample goods carrier','Sample farm transport'],animal?'Sample livestock carrier':cold?'Sample temperature-controlled carrier':'Sample goods carrier')}${field(L('Pickup point','పికప్ ప్రాంతం'),'pickup',d.location,'text','required maxlength="100"')}${field(L('Drop point','డెలివరీ ప్రాంతం'),'drop',state.profile.city,'text','required maxlength="100"')}${field(L('Pickup date','పికప్ తేదీ'),'date',future(3),'date',`required min="${today()}"`)}${select(L('Time slot','సమయం'),'slot',['06:00–08:00','09:00–11:00','14:00–16:00'],'09:00–11:00')}<div class="card"><h3>${L('Demo readiness checklist','నమూనా సిద్ధత తనిఖీ')}</h3>${(animal?['Ownership and animal identification records reviewed','Applicable veterinary fitness / movement documents reviewed','Suitable vehicle, loading, space, feed and water arranged']:cold?['Harvest / collection time agreed','Suitable temperature, packing and handling agreed','Weighment and acceptance conditions agreed']:['Packing and loading agreed','Weighment and quantity checks agreed','Buyer / seller transport responsibility agreed']).map((x,i)=>`<label class="check"><input type="checkbox" name="check${i}" required><span>${esc(x)}</span></label>`).join('')}<p class="small muted">${L('This checklist demonstrates the flow. Actual requirements depend on goods, species and route.','ఈ జాబితా ప్రక్రియ నమూనా మాత్రమే. నిజమైన అవసరాలు సరుకు, జాతి మరియు మార్గంపై ఆధారపడి ఉంటాయి.')}</p></div><div class="notice gold">${L('Illustrative transport quote','నమూనా రవాణా ధర')}: ${money(animal?2500:cold?1900:1500)}. ${L('Charged separately from product value; no payment is collected.','సరుకు విలువకు వేరుగా ఉంటుంది; డబ్బు వసూలు చేయరు.')}</div>${errorBox()}${submit(L('Confirm demo transport','నమూనా రవాణా నిర్ధారణ'))}</form>`);}
function receiptForm(){const d=getDeal(ui.params.id);return shell(L('Confirm receipt','స్వీకరణ నిర్ధారణ'),`<h1>${L('Close the trade clearly.','వ్యాపారం స్పష్టంగా పూర్తి చేయండి.')}</h1><p class="lead">${esc(d.title)} · ${d.quantity} ${unit(d.unit)}</p><form data-form="receipt" data-id="${d.id}">${field(L('Quantity received','అందిన పరిమాణం'),'quantity',d.quantity,'number',`required min="0.01" max="${d.quantity}" step="${['animal','bird','egg','fish'].includes(d.unit)?'1':'0.01'}"`)}${textarea(L('Receipt notes','స్వీకరణ వివరాలు'),'notes','Sample goods received as agreed.','required maxlength="600"')}<label class="check"><input name="accepted" type="checkbox" required><span>${L('Record demo acceptance of quality and quantity','నాణ్యత మరియు పరిమాణం నమూనా అంగీకారం')}</span></label><label class="check"><input name="settled" type="checkbox" required><span>${L('Record fictional payment of the remaining product balance. No money moves.','మిగిలిన సరుకు మొత్తానికి కల్పిత చెల్లింపు నమోదు. నిజమైన డబ్బు మారదు.')}</span></label>${note('To demonstrate a short delivery or quality problem, raise a dispute instead of confirming acceptance.','తక్కువ డెలివరీ లేదా నాణ్యత సమస్యను చూపడానికి అంగీకారం బదులు వివాదం నమోదు చేయండి.')}${errorBox()}${submit(L('Complete demo transaction','నమూనా లావాదేవీ పూర్తి చేయండి'))}</form><button class="link spaced" data-action="dispute" data-id="${d.id}">${L('Report an issue / short delivery','సమస్య / తక్కువ డెలివరీ నివేదించండి')} →</button>`);}
function inboxPage(){return shell(L('Messages','సందేశాలు'),`<h1>${L('Trade conversations','వ్యాపార చర్చలు')}</h1><p class="lead">${L('Enquiries and simulated replies stay on this device.','విచారణలు మరియు నమూనా సమాధానాలు ఈ పరికరంలోనే ఉంటాయి.')}</p>${state.chats.map(c=>`<button class="chat-list" data-action="open-chat" data-id="${c.id}"><div class="avatar">${esc(c.party.slice(0,2).toUpperCase())}</div><div class="info"><strong>${esc(c.party)}</strong><p>${esc(c.messages[c.messages.length-1]?.text||'Start an enquiry')}</p></div>${icon('chevron')}</button>`).join('')||empty(L('No conversations','చర్చలు లేవు'),L('Open a listing and tap Enquire.','లిస్టింగ్‌లో విచారించండి నొక్కండి.'))}`,'home');}
function chatPage(){const c=state.chats.find(c=>c.id===ui.params.id);if(!c)return inboxPage();const p=getListing(c.listingId);return shell(esc(c.party),`${p?`<button class="option" data-action="detail" data-id="${p.id}"><img src="art/${p.image}.svg" alt=""><div><strong>${esc(title(p))}</strong><p>${money(p.price)}/${unit(p.unit)}</p></div>${icon('chevron')}</button>`:''}${note('Local demo chat. Messages are not sent to real people.','స్థానిక నమూనా చాట్. సందేశాలు నిజమైన వ్యక్తులకు పంపబడవు.')}<div class="chips"><button class="chip" data-action="quick-chat" data-id="Is this lot available?">${L('Available?','లభ్యమా?')}</button><button class="chip" data-action="quick-chat" data-id="Can I arrange an inspection?">${L('Inspection?','తనిఖీ?')}</button><button class="chip" data-action="quick-chat" data-id="Please confirm pickup conditions.">${L('Pickup terms','పికప్ నిబంధనలు')}</button></div><div id="chat-messages">${c.messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text)}<small>${m.mine?L('You · local message','మీరు · స్థానిక సందేశం'):L('Demo reply · simulated','నమూనా సమాధానం')} · ${new Date(m.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')}</div>${p?`<button class="link" data-action="offer" data-id="${p.id}">${L('Turn this enquiry into an offer','విచారణ నుంచి ప్రతిపాదనకు')} →</button>`:''}`,'',false,'',`<form class="chat-compose" data-form="chat" data-id="${c.id}"><input name="message" maxlength="600" required placeholder="${L('Write a demo message…','నమూనా సందేశం రాయండి…')}" aria-label="Message"><button type="submit" aria-label="Send demo message">${icon('send')}</button></form>`);}
function notificationsPage(){return shell(L('Notifications','నోటిఫికేషన్లు'),`<div class="row"><h1>${L('Your updates','మీ సమాచారం')}</h1><button class="link" data-action="read-all">${L('Read all','అన్నీ చదివాను')}</button></div><div class="spaced">${state.notifications.map(n=>`<button class="chat-list" data-action="open-notification" data-id="${n.id}"><div class="avatar">${icon(n.read?'check':'bell')}</div><div class="info"><strong>${esc(L(n.title,n.te))}</strong><p>${n.read?L('Read','చదివాను'):L('New demo update','కొత్త నమూనా సమాచారం')}</p></div>${icon('chevron')}</button>`).join('')}</div>`,'account');}
const menu=(i,t,sub,action)=>`<button class="menu-row" data-action="${action}"><span class="menu-icon">${icon(i)}</span><span class="info"><strong>${t}</strong><small>${sub}</small></span>${icon('chevron')}</button>`;
function accountPage(){const own=state.listings.filter(p=>p.own).length,closed=state.deals.filter(d=>d.stage==='complete').length;return shell(L('Your account','మీ ఖాతా'),`<div class="account-hero"><div class="person"><div class="avatar">${esc(state.profile.name.slice(0,2).toUpperCase())}</div><div class="info"><h2>${esc(state.profile.name)}</h2><p class="small">${esc(state.profile.business)} · ${esc(state.profile.city)}</p></div></div><button class="btn cream spaced" data-action="switch-role">${L('Switch to','మోడ్ మార్చండి')}: ${state.profile.role==='buyer'?L('Selling mode','అమ్మకం మోడ్'):L('Buying mode','కొనుగోలు మోడ్')}</button></div><div class="stat-grid"><div class="stat"><strong>${own}</strong><small>${L('Your listings','మీ లిస్టింగ్‌లు')}</small></div><div class="stat"><strong>${closed}</strong><small>${L('Completed demo trades','పూర్తయిన నమూనా వ్యాపారాలు')}</small></div></div><div class="card">${menu('user',L('Profile and language','ప్రొఫైల్ మరియు భాష'),L('Name, business type, English / Telugu','పేరు, వ్యాపార రకం, ఇంగ్లీష్ / తెలుగు'),'profile')}${menu('leaf',L('My listings','నా లిస్టింగ్‌లు'),L('Edit, pause, sold status and expiry','మార్పులు, నిలిపివేత, అమ్మకం మరియు గడువు'),'manage-listings')}${menu('heart',L('Saved listings','సేవ్ చేసిన లిస్టింగ్‌లు'),L('Your buying shortlist','మీ కొనుగోలు ఎంపికలు'),'saved')}${menu('request',L('My requirements','నా అవసరాలు'),L('Requirements and supplier quotes','అవసరాలు మరియు సరఫరాదారు ప్రతిపాదనలు'),'my-requests')}${menu('chat',L('Messages','సందేశాలు'),L('Local enquiries and demo replies','స్థానిక విచారణలు మరియు నమూనా సమాధానాలు'),'inbox')}${menu('calendar',L('Services and bookings','సేవలు మరియు బుకింగ్‌లు'),L('Inspections, visits and transport','తనిఖీలు, సందర్శనలు మరియు రవాణా'),'services')}${menu('star',L('Buyer Pro and promotion','బయ్యర్ ప్రో మరియు ప్రచారం'),L('Sample subscription and sponsored listings','నమూనా చందా మరియు ప్రాయోజిత లిస్టింగ్‌లు'),'plans')}${menu('wallet',L('Payment records','చెల్లింపు రికార్డులు'),L('Fictional advances and settlements','కల్పిత అడ్వాన్స్ మరియు చెల్లింపులు'),'payments')}${menu('help',L('Help and support','సహాయం మరియు సపోర్ట్'),L('Report listings, disputes and sample tickets','ఫిర్యాదులు, వివాదాలు మరియు నమూనా టికెట్లు'),'support')}${menu('chart',L('Demo management console','నమూనా నిర్వహణ'),L('Moderation and marketplace analytics','నిర్వహణ మరియు మార్కెట్ విశ్లేషణ'),'admin')}</div>${note('Offline prototype v1.0. No connected live marketplace, real verification, insurance, payment protection or public listing links.','ఆఫ్‌లైన్ నమూనా v1.0. లైవ్ సర్వర్, నిజమైన ధృవీకరణ, బీమా, చెల్లింపు రక్షణ లేదా పబ్లిక్ లింకులు లేవు.')}`,'account');}
function profilePage(){return shell(L('Profile and language','ప్రొఫైల్ మరియు భాష'),`<h1>${L('Make it yours.','మీ ప్రొఫైల్ మార్చండి.')}</h1><form data-form="profile">${field(L('Name / business name','పేరు / వ్యాపార పేరు'),'name',state.profile.name,'text','required minlength="2" maxlength="60"')}${select(L('Business type','వ్యాపార రకం'),'business',['Individual','Farmer','FPO','Trader','Miller','Processor','Dairy farmer','Poultry farmer','Aqua farmer'],state.profile.business)}${select(L('Demo location','నమూనా ప్రాంతం'),'city',['Guntur','Mangalagiri','Vijayawada','Tenali','Ongole','Nellore','Nuzvid','Bhimavaram','Khammam'],state.profile.city)}${select(L('Interface language','ఇంటర్‌ఫేస్ భాష'),'language',[['en','English'],['te','తెలుగు']],state.profile.language)}${errorBox()}${submit(L('Save profile','ప్రొఫైల్ సేవ్ చేయండి'))}</form><div class="card spaced"><h3>${L('Data controls','డేటా నియంత్రణ')}</h3><p class="small muted">${L('Listings, chats, deals and settings persist on this device. Reset restores the original demo dataset.','లిస్టింగ్‌లు, చాట్‌లు, ఒప్పందాలు మరియు సెట్టింగ్‌లు ఈ పరికరంలో ఉంటాయి. రీసెట్ చేస్తే తొలి నమూనా డేటా వస్తుంది.')}</p><button class="link spaced" data-action="reset-confirm">${L('Reset all demo data','నమూనా డేటా రీసెట్ చేయండి')}</button></div>`,'account');}
function servicesPage(){const booked=state.deals.filter(d=>d.inspection||d.delivery);return shell(L('Services and bookings','సేవలు మరియు బుకింగ్‌లు'),`<h1>${L('Support around the trade.','వ్యాపారం చుట్టూ సేవలు.')}</h1><p class="lead">${L('Try the inspection and transport booking flows from an active deal.','కొనసాగుతున్న ఒప్పందంలో తనిఖీ మరియు రవాణా బుకింగ్ ప్రయత్నించండి.')}</p><div class="card"><div class="person"><div class="avatar">${icon('shield')}</div><div class="info"><h3>${L('Quality and animal checks','నాణ్యత మరియు జంతువు తనిఖీలు')}</h3><p>${L('Sample lab, veterinary assessment and farm visits.','నమూనా ల్యాబ్, వెటర్నరీ తనిఖీ మరియు ఫార్మ్ సందర్శనలు.')}</p></div></div></div><div class="card"><div class="person"><div class="avatar">${icon('truck')}</div><div class="info"><h3>${L('Suitable transport','తగిన రవాణా')}</h3><p>${L('Goods, livestock, chilled produce and fish seed.','సరుకు, పశువులు, చల్లని నిల్వ మరియు చేప పిల్లలు.')}</p></div></div></div>${btn(L('Open active deals','ఒప్పందాలు చూడండి'),'deals')}<div class="section-head"><h2>${L('Your demo bookings','మీ నమూనా బుకింగ్‌లు')}</h2></div>${booked.length?booked.map(d=>`<div class="card"><h3>${esc(d.title)}</h3>${d.inspection?`<p class="small muted">${esc(d.inspection.type)} · ${d.inspection.date} · ${d.inspection.status}</p>`:''}${d.delivery?`<p class="small muted spaced">${esc(d.delivery.partner)} · ${d.delivery.date} · ${d.delivery.phase}</p>`:''}<button class="link spaced" data-action="deal" data-id="${d.id}">${L('Open booking','బుకింగ్ చూడండి')} →</button></div>`).join(''):empty(L('No bookings yet','ఇంకా బుకింగ్‌లు లేవు'),L('Try the sample dairy deal to arrange an inspection.','పశువుల నమూనా ఒప్పందంలో తనిఖీ ఏర్పాటు చేయండి.'))}`,'account');}
function plansPage(){const own=state.listings.filter(p=>p.own&&p.status==='active');return shell(L('Plans and promotion','ప్లాన్‌లు మరియు ప్రచారం'),`<h1>${L('Tools for regular traders.','నిత్యం వ్యాపారం చేసేవారికి.')}</h1><p class="lead">${L('Basic farmer listings remain free in this proposed model. All prices below are illustrative.','ఈ ప్రతిపాదిత విధానంలో రైతుల ప్రాథమిక లిస్టింగ్‌లు ఉచితం. కింది ధరలు నమూనాలు మాత్రమే.')}</p><div class="plans"><div class="eyebrow">BUYER PRO · DEMO</div><h2>${L('Find the right supply faster.','సరైన సరుకు త్వరగా చూడండి.')}</h2><div class="price">₹499 <small style="font-size:15px;font-weight:500">/ ${L('month','నెల')}</small></div><ul><li>${L('Saved sourcing requirements','సేవ్ చేసిన అవసరాలు')}</li><li>${L('Category and location alerts','వర్గం మరియు ప్రాంతం సమాచారం')}</li><li>${L('Quote comparison and trade records','ధర పోలిక మరియు వ్యాపార రికార్డులు')}</li></ul>${btn(state.subscription?L('Demo plan active','నమూనా ప్లాన్ ప్రారంభమైంది'):L('Activate sample plan','నమూనా ప్లాన్ ప్రారంభించండి'),'activate-plan','','cream')}</div><div class="card"><h3>${L('Promote a listing','లిస్టింగ్ ప్రచారం')}</h3><p class="small muted">${L('Illustrative ₹149 / 7 days. Promoted cards are labelled Sponsored · demo. No money is charged.','నమూనా ₹149 / 7 రోజులు. ప్రచార కార్డులకు నమూనా గుర్తింపు ఉంటుంది. డబ్బు వసూలు చేయరు.')}</p>${own.length?`<form data-form="promotion">${select(L('Your active listing','మీ లిస్టింగ్'),'listingId',own.map(p=>[p.id,title(p)]),own[0].id)}${submit(L('Simulate promotion','నమూనా ప్రచారం'))}</form>`:`<button class="link spaced" data-action="start-sell">${L('Create a listing first','ముందు లిస్టింగ్ సృష్టించండి')} →</button>`}</div>${note('Service fees and commercial plans must be validated with real buyers before launch. No paid service is active in this APK.','ప్రారంభానికి ముందు సేవ రుసుములు మరియు వ్యాపార ప్లాన్‌లను నిజమైన కొనుగోలుదారులతో పరీక్షించాలి. ఈ APKలో నిజమైన చెల్లింపు సేవ లేదు.')}`,'account');}
function paymentsPage(){const records=state.deals.flatMap(d=>d.payments.map(p=>({...p,deal:d})));return shell(L('Payment records','చెల్లింపు రికార్డులు'),`<h1>${L('Demo money trail','నమూనా చెల్లింపు రికార్డులు')}</h1><p class="lead">${L('These entries are fictional records. No bank or payment gateway is connected.','ఇవి కల్పిత రికార్డులు. బ్యాంకు లేదా చెల్లింపు సేవ కనెక్ట్ కాలేదు.')}</p>${records.length?records.map(p=>`<div class="card"><div class="row"><h3>${money(p.amount)}</h3><span class="tag">DEMO</span></div><p class="small muted">${esc(p.method)} · ${esc(p.kind)}</p><p class="small muted spaced">${esc(p.deal.title)} · ${p.id}</p><button class="link spaced" data-action="deal-document" data-id="${p.deal.id}">${L('Open receipt summary','చెల్లింపు సారాంశం')} →</button></div>`).join(''):empty(L('No payment records yet','ఇంకా చెల్లింపు రికార్డులు లేవు'),L('Try the advance payment step in a sample deal.','నమూనా ఒప్పందంలో అడ్వాన్స్ చెల్లింపు ప్రయత్నించండి.'),btn(L('Open deals','ఒప్పందాలు చూడండి'),'deals'))}`,'account');}
function documentPage(){const kind=ui.params.kind||'deal',d=getDeal(ui.params.id),p=getListing(ui.params.id);let h='',body='';
 if(kind==='listing'&&p){h=p.quality==='samplevet'?L('Sample veterinary report','నమూనా వెటర్నరీ రిపోర్ట్'):L('Sample lot quality report','నమూనా సరుకు నాణ్యత రిపోర్ట్');body=`<h3>${esc(title(p))}</h3><p>${p.id} · ${esc(p.location)}</p><div class="invoice-row"><span>${L('Report date','రిపోర్ట్ తేదీ')}</span><strong>${today()}</strong></div><div class="invoice-row"><span>${L('Issuer','రిపోర్ట్ ఇచ్చినవారు')}</span><strong>Demo inspection team</strong></div>${p.specs.map(([k,v])=>`<div class="invoice-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<h3>${L('Sample assessment','నమూనా తనిఖీ')}</h3><p>This document demonstrates the report layout. The listed measurements are seller declarations or fictional examples. No actual inspection, diagnosis, milk-yield test or laboratory analysis has taken place.</p>`;}
 else if(kind==='inspection'&&d&&d.inspection){h=L('Sample inspection report','నమూనా తనిఖీ రిపోర్ట్');body=`<h3>${esc(d.title)}</h3><p>${d.id} · ${esc(d.location)}</p>${[['Service',d.inspection.type],['Demo provider',d.inspection.provider],['Visit date',d.inspection.date],['Status',d.inspection.status],['Sample outcome',d.inspection.outcome||'Pending']].map(([k,v])=>`<div class="invoice-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<h3>Sample findings</h3><p>${esc(d.inspection.findings||'Inspection has not been recorded yet.')}</p><h3>Fee illustration</h3><p>${money(d.inspection.fee)} — separate from goods value; no money was collected.</p>`;}
 else if(d){h=L('Demo deal summary','నమూనా ఒప్పంద సారాంశం');body=`<h3>${esc(d.title)}</h3><p>${d.id} · ${today()}</p>${[['Buyer',d.buyer],['Seller',d.seller],['Quantity',d.quantity+' '+unit(d.unit)],['Unit price',money(d.price)],['Product value',money(dealTotal(d))],['Fictional payments recorded',money(paid(d))],['Product balance',money(remaining(d))],['Stage',stageLabel(d.stage)]].map(([k,v])=>`<div class="invoice-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<h3>Trade terms</h3><p>${esc(d.terms?.quality||'Terms have not been agreed yet.')}</p><p>${esc(d.terms?.cancellation||'')}</p><p>${esc(d.terms?.transport||'')} · ${esc(d.terms?.weighment||'')}</p><h3>Inspection and transport</h3><p>${d.inspection?esc(d.inspection.provider)+' · '+d.inspection.status+' · '+money(d.inspection.fee)+' illustrative fee':'No inspection arranged / recorded.'}</p><p>${d.delivery?esc(d.delivery.partner)+' · '+d.delivery.phase+' · '+money(d.delivery.fee)+' illustrative fee':'Transport has not been arranged.'}</p><h3>Fictional payment records</h3>${d.payments.length?d.payments.map(p=>`<p>${p.id} · ${money(p.amount)} · ${esc(p.method)} · ${esc(p.kind)}</p>`).join(''):'<p>None recorded.</p>'}${d.receipt?`<h3>Receipt notes</h3><p>${esc(d.receipt.notes)}</p>`:''}`;}
 else return shell('Document',empty('Document unavailable','Open a listing or deal.'));
 return shell(L('Document preview','పత్రం ప్రివ్యూ'),`<article class="document"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div class="brandname">Agromitra<span>MARKET</span></div></div><h1>${h}</h1><div class="doc-watermark">SAMPLE ONLY · NO REAL CERTIFICATION OR PAYMENT</div>${body}<h3>Prototype notice</h3><p>All parties, reports, verification badges, bookings and payment records are fictional demonstrations stored on this device. This document is not a health certificate, laboratory certificate, tax invoice, proof of payment or real sale agreement.</p></article><div class="print-actions spaced">${btn(icon('doc')+L('Print / Save PDF','ప్రింట్ / PDF సేవ్'),'print-document','','secondary')}</div>`);}
function supportPage(){return shell(L('Support workspace','సపోర్ట్ నిర్వహణ'),`<h1>${L('Resolve trade issues.','వ్యాపార సమస్యల పరిష్కారం.')}</h1><p class="lead">${L('Create and review local demonstration tickets.','స్థానిక నమూనా టికెట్లు సృష్టించి చూడండి.')}</p>${btn(L('Create support ticket','సపోర్ట్ టికెట్ సృష్టించండి'),'new-ticket')}<button class="link spaced" data-action="help">${L('How the marketplace works','మార్కెట్ ఎలా పనిచేస్తుంది')} →</button><div class="section-head"><h2>${L('Your tickets','మీ టికెట్లు')}</h2></div>${state.tickets.length?state.tickets.map(t=>`<div class="card"><div class="row"><h3>${esc(t.subject)}</h3><span class="tag ${t.status==='Resolved'?'':'gold'}">${esc(t.status)}</span></div><p class="small muted">${t.id} · ${esc(t.reason)}</p><p class="small muted spaced">${esc(t.description)}</p>${t.dealId?`<button class="link spaced" data-action="deal" data-id="${t.dealId}">${L('Open linked deal','సంబంధిత ఒప్పందం')} →</button>`:''}${t.status==='Open'?`<button class="btn secondary spaced" data-action="resolve-ticket" data-id="${t.id}">${L('Simulate resolution','నమూనా పరిష్కారం')}</button>`:`<p class="small spaced">${esc(t.resolution||'Resolved in sample console.')}</p>`}</div>`).join(''):empty(L('No tickets yet','ఇంకా టికెట్లు లేవు'),L('A listing report or deal dispute appears here.','లిస్టింగ్ ఫిర్యాదు లేదా ఒప్పంద వివాదం ఇక్కడ కనిపిస్తుంది.'))}`,'account');}
function ticketForm(){const d=getDeal(ui.params.dealId),p=getListing(ui.params.listingId);return shell(d?L('Raise a dispute','వివాదం నమోదు'):p?L('Report listing','లిస్టింగ్ ఫిర్యాదు'):L('Support ticket','సపోర్ట్ టికెట్'),`<h1>${L('Tell us what happened.','ఏం జరిగిందో చెప్పండి.')}</h1><p class="lead">${L('This creates a local demo ticket. No support team is contacted.','ఇది స్థానిక నమూనా టికెట్. నిజమైన సపోర్ట్ బృందాన్ని సంప్రదించరు.')}</p><form data-form="ticket" data-deal-id="${d?.id||''}" data-listing-id="${p?.id||''}">${field(L('Subject','విషయం'),'subject',d?'Issue with '+d.title:p?'Report: '+p.title:'','text','required minlength="3" maxlength="100"')}${select(L('Reason','కారణం'),'reason',d?['Quality differs','Short delivery','Payment record issue','Transport issue','Other']:['Misleading information','Duplicate listing','Suspected fraud','Animal welfare concern','Other'],'Misleading information')}${textarea(L('Describe the issue','సమస్య వివరాలు'),'description','','required minlength="10" maxlength="1500"')}${d?note('Completion will pause while the demo dispute remains open.','నమూనా వివాదం పరిష్కరించే వరకు ఒప్పందం పూర్తి చేయడం నిలిపివేయబడుతుంది.'):''}${errorBox()}${submit(L('Submit demo ticket','నమూనా టికెట్ నమోదు'))}</form>`);}
function helpPage(){return shell(L('How it works','ఎలా పనిచేస్తుంది'),`<h1>${L('From listing to a clear trade.','లిస్టింగ్ నుంచి స్పష్టమైన వ్యాపారం.')}</h1><p class="lead">${L('Use either buyer or seller mode to explore the complete flow.','పూర్తి ప్రక్రియ కోసం కొనుగోలు లేదా అమ్మకం మోడ్ ఉపయోగించండి.')}</p>${[['1. Discover','Browse all eight segments, search nearby sample stock, filter quantity/price and save listings.'],['2. Connect','Enquire through local chat, make an offer or respond to a buyer requirement.'],['3. Check','Arrange a sample farm visit, veterinary assessment or lot-quality inspection.'],['4. Agree','Record price, quantity, quality conditions, rejection terms and transport responsibility.'],['5. Arrange','Simulate an advance or payment-on-pickup arrangement, then book appropriate transport.'],['6. Complete','Record pickup, delivery, acceptance, fictional settlement and a review.'],['For sellers','Post category-specific details, preview the listing, manage stock, expiry and sold status.'],['Public marketplace concept','Buyers can browse all active listings. Real public web links, shared accounts and multi-user communication require a live backend.']].map(([h,p])=>`<div class="card"><h3>${h}</h3><p class="small muted">${p}</p></div>`).join('')}${note('Prototype limits: all listings and replies are samples; voice listing uses sample transcripts; illustrations stand in for uploaded photos; calling is a preview; payments, verification and services are simulated. Native PDF printing is available from document previews.','నమూనా పరిమితులు: లిస్టింగ్‌లు మరియు సమాధానాలు నమూనాలు. వాయిస్ లిస్టింగ్‌లో నమూనా వాక్యాలు, ఫోటోల బదులు చిత్రాలు, కాల్ ప్రివ్యూ ఉపయోగిస్తాయి. చెల్లింపులు మరియు సేవలు నమూనాలు. పత్రం ప్రివ్యూ నుంచి PDF ప్రింటింగ్ లభిస్తుంది.')}`,'account');}
function adminPage(){const rows=state.listings.filter(available),max=Math.max(...MD.categories.map(c=>rows.filter(p=>p.cat===c.id).length),1),volume=state.deals.filter(d=>d.stage==='complete').reduce((a,d)=>a+dealTotal(d),0);return shell(L('Demo management console','నమూనా నిర్వహణ'),`<h1>${L('Marketplace overview','మార్కెట్ వివరాలు')}</h1><p class="lead">${L('Local management demonstration. This is not an authenticated admin portal.','స్థానిక నిర్వహణ నమూనా. ఇది నిజమైన అడ్మిన్ లాగిన్ కాదు.')}</p><div class="stat-grid"><div class="stat"><strong>${rows.length}</strong><small>${L('Active listings','లిస్టింగ్‌లు')}</small></div><div class="stat"><strong>${state.requests.filter(r=>r.status==='open').length}</strong><small>${L('Open requirements','కొనసాగుతున్న అవసరాలు')}</small></div><div class="stat"><strong>${state.deals.length}</strong><small>${L('Demo deals','నమూనా ఒప్పందాలు')}</small></div><div class="stat"><strong>${money(volume)}</strong><small>${L('Completed demo trade value','పూర్తయిన నమూనా వ్యాపార విలువ')}</small></div></div><div class="card"><h3>${L('Listings by segment','వర్గం ప్రకారం లిస్టింగ్‌లు')}</h3><div class="bar-chart">${MD.categories.map(c=>{const n=rows.filter(p=>p.cat===c.id).length;return `<div class="bar-row"><span>${L(c.name,c.te)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><strong>${n}</strong></div>`;}).join('')}</div></div><div class="card">${menu('shield',L('Listing moderation','లిస్టింగ్ నిర్వహణ'),L('Visibility, sample identity badges and expiry','లభ్యత, నమూనా గుర్తింపు మరియు గడువు'),'moderation')}${menu('help',L('Reports and disputes','ఫిర్యాదులు మరియు వివాదాలు'),state.tickets.filter(t=>t.status==='Open').length+' '+L('open local tickets','కొనసాగుతున్న టికెట్లు'),'support')}${menu('doc',L('Sample trade reports','నమూనా వ్యాపార రిపోర్టులు'),L('View and print deal documents','ఒప్పంద పత్రాలు చూడండి / ప్రింట్ చేయండి'),'deals')}</div>`,'account');}
function moderationPage(){return shell(L('Listing moderation','లిస్టింగ్ నిర్వహణ'),`<h1>${L('Review sample listings','నమూనా లిస్టింగ్‌ల సమీక్ష')}</h1>${note('A sample badge is a UI demonstration. It does not verify a real seller, quality or animal health.','నమూనా బ్యాడ్జ్ ఇంటర్‌ఫేస్ నమూనా. ఇది నిజమైన విక్రేత, నాణ్యత లేదా జంతువు ఆరోగ్యాన్ని ధృవీకరించదు.')} ${state.listings.map(p=>`<div class="deal-card"><div class="row"><img class="thumb" src="art/${p.image}.svg" alt=""><div style="flex:1"><h3>${esc(title(p))}</h3><p>${p.id} · ${esc(p.status)} · ${p.expires}</p><p>${p.identity==='sample'?'Sample identity badge':'Identity not checked'}</p></div></div><div class="inline-actions"><button data-action="toggle-listing" data-id="${p.id}">${p.status==='active'?L('Pause','నిలిపివేయండి'):L('Activate','ప్రారంభించండి')}</button><button data-action="sample-verify" data-id="${p.id}">${L('Toggle sample ID badge','నమూనా గుర్తింపు మార్చండి')}</button><button data-action="expire-listing" data-id="${p.id}">${L('Expire','గడువు ముగించండి')}</button><button data-action="detail" data-id="${p.id}">${L('View','చూడండి')}</button></div></div>`).join('')}`,'account');}
function successPage(){return shell(L('Saved successfully','సేవ్ అయింది'),`<div class="success"><div class="seal">${icon('check')}</div><h1>${esc(ui.params.title||L('Your demo listing is live.','మీ నమూనా లిస్టింగ్ కనిపిస్తుంది.'))}</h1><p>${esc(ui.params.message||L('Find it in the marketplace and manage it from your account.','మార్కెట్‌లో చూడండి మరియు మీ ఖాతా నుంచి నిర్వహించండి.'))}</p>${ui.params.listingId?btn(L('View listing','లిస్టింగ్ చూడండి'),'detail',ui.params.listingId):ui.params.dealId?btn(L('Open deal','ఒప్పందం చూడండి'),'deal',ui.params.dealId):btn(L('View requirements','అవసరాలు చూడండి'),'requests')}<div class="spaced">${btn(L('Back to marketplace','మార్కెట్‌కు తిరిగి'),'home','','secondary')}</div></div>`);}
const ROUTES={home,browse,detail,welcome,onboard,saved:savedPage,requests:requestsPage,'request-detail':requestDetail,'request-form':requestForm,offer:offerForm,sell:sellPage,'manage-listings':manageListings,deals:dealsPage,deal:dealPage,inspection:inspectionForm,'inspection-results':inspectionResults,agreement:agreementForm,payment:paymentForm,transport:transportForm,receipt:receiptForm,inbox:inboxPage,chat:chatPage,notifications:notificationsPage,account:accountPage,profile:profilePage,services:servicesPage,plans:plansPage,payments:paymentsPage,document:documentPage,support:supportPage,ticket:ticketForm,help:helpPage,admin:adminPage,moderation:moderationPage,success:successPage};
function render(){document.documentElement.lang=state.profile.language;document.getElementById('app').innerHTML=(ROUTES[ui.route]||home)();}
function openChat(listingId,party){let c=state.chats.find(c=>c.listingId===listingId&&c.party===party);if(!c){c={id:uid('C'),listingId,party,messages:[{mine:false,text:L('Welcome. Please confirm the quantity, inspection and pickup requirements.','స్వాగతం. పరిమాణం, తనిఖీ మరియు పికప్ అవసరాలు చెప్పండి.'),demo:true,time:Date.now()}]};state.chats.push(c);save();}go('chat',{id:c.id});}
function sendMessage(c,text){if(!text.trim())return;const clean=text.trim().slice(0,600);c.messages.push({mine:true,text:clean,time:Date.now()},{mine:false,text:L('Sample reply: availability is shown in the listing. We can arrange a farm visit before agreeing price and pickup.','నమూనా సమాధానం: లభ్యత లిస్టింగ్‌లో ఉంది. ధర మరియు పికప్ ముందు ఫార్మ్ సందర్శన ఏర్పాటు చేయవచ్చు.'),demo:true,time:Date.now()});save();render();}
function photoModal(){modal(L('Choose a demo image','నమూనా చిత్రం ఎంచుకోండి'),`<p>${L('Photo selection uses sample illustrations here. Camera and gallery uploads are intended for the live marketplace.','నమూనా చిత్రం ఎంపిక. కెమెరా మరియు గ్యాలరీ ఫోటోల కోసం ప్రొడక్షన్ అనుసంధానం అవసరం.')}</p><div class="photo-grid spaced">${['paddy','maize','chilli','groundnut','cotton','tomato','banana','mango','buffalo','cow','bull','goat','sheep','chicken','layer','rooster','chicks','eggs','fish','prawn','fishseed','milk'].map(k=>`<button class="photo-choice ${ui.draft.image===k?'selected':''}" data-action="photo-select" data-id="${k}"><img src="art/${k}.svg" alt="${k}"><span>${k}</span></button>`).join('')}</div>`);}
function voiceModal(category='crops'){const p=MD.listings.find(p=>p.cat===category);const text=state.profile.language==='te'?`నా దగ్గర ${p.quantity} ${unit(p.unit)} ${p.te} ఉంది. ధర ₹${p.price} ప్రతి ${unit(p.unit)}. ప్రాంతం ${p.location}.`:`I have ${p.quantity} ${p.unit} of ${p.title}. Price ₹${p.price} per ${p.unit}. Location ${p.location}.`;modal(L('Voice listing demo','వాయిస్ లిస్టింగ్ నమూనా'),`${note('This uses an example transcript to demonstrate editable listing fields. It does not record audio or call an AI service.','ఇది నమూనా వాక్యాన్ని లిస్టింగ్ వివరాలుగా చూపిస్తుంది. ఆడియో రికార్డు లేదా AI సేవను ఉపయోగించదు.')}<form data-form="voice">${select(L('Example segment','నమూనా వర్గం'),'category',MD.categories.map(c=>[c.id,L(c.name,c.te)]),category)}${textarea(L('Sample spoken transcript','నమూనా మాట్లాడిన వాక్యం'),'transcript',text,'required')}<div class="form-error" id="form-error"></div>${submit(L('Preview interpreted fields','వివరాల నమూనా ప్రివ్యూ'))}</form>`);}
function filterModal(){const f=ui.filters;modal(L('Find the right listing','సరైన లిస్టింగ్ చూడండి'),`<form data-form="filters">${select(L('Location','ప్రాంతం'),'location',['All',...new Set(state.listings.map(p=>p.location))],f.location)}${select(L('Demo distance','నమూనా దూరం'),'distance',[['0',L('Any distance','ఏ దూరమైనా')],['25','25 km'],['50','50 km'],['100','100 km'],['200','200 km']],String(f.distance))}${field(L('Maximum price per listing unit (₹)','లిస్టింగ్ యూనిట్‌కు గరిష్ఠ ధర (₹)'),'price',f.price||'','number','min="0" step="0.01"',L('Prices use different units across segments.','వర్గాల్లో ధర యూనిట్‌లు వేరుగా ఉంటాయి.'))}${field(L('Minimum available quantity','కనీస లభ్య పరిమాణం'),'quantity',f.quantity||'','number','min="0" step="0.01"')}${select(L('Quantity unit','పరిమాణ యూనిట్'),'unit',[['all',L('Any unit','ఏ యూనిట్ అయినా')],...['quintal','kg','animal','bird','egg','litre','fish'].map(u=>[u,unit(u)])],f.unit||'all')}${select(L('Report availability','రిపోర్ట్ లభ్యత'),'quality',[['all',L('Any listing','ఏ లిస్టింగ్ అయినా')],['reports',L('Has sample inspection report','నమూనా తనిఖీ రిపోర్ట్ ఉంది')]],f.quality)}${select(L('Sort','క్రమం'),'sort',[['recent',L('Recently listed','కొత్త లిస్టింగ్‌లు')],['near',L('Nearest demo distance','దగ్గర నమూనా దూరం')],['low',L('Price per unit: low to high','యూనిట్ ధర: తక్కువ నుంచి ఎక్కువ')],['high',L('Price per unit: high to low','యూనిట్ ధర: ఎక్కువ నుంచి తక్కువ')]],f.sort)}${submit(L('Apply filters','ఫిల్టర్లు అమలు'))}</form>`);}
function handleAction(a,id='',element=null){const d=getDeal(id),p=getListing(id);switch(a){
 case 'nav':if(id==='sell'){ui.draft=newDraft();tab('sell');ui.params={step:1};render();}else tab(id);break;
 case 'home':tab('home');break;case 'back':window.handleAndroidBack();break;case 'close-modal':closeModal();break;
 case 'browse':go('browse');break;case 'category':ui.filters={...ui.filters,cat:id,query:''};go('browse');break;
 case 'browse-cat':ui.filters.cat=id;render();break;case 'filters':filterModal();break;
 case 'clear-filters':ui.filters={cat:'all',query:'',distance:0,price:0,quantity:0,unit:'all',quality:'all',sort:'recent',location:'All'};render();break;
 case 'detail':go('detail',{id});break;case 'save-listing':state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?L('Listing saved','లిస్టింగ్ సేవ్ అయింది'):L('Removed from saved','సేవ్ జాబితా నుంచి తొలగించబడింది'));break;
 case 'language':state.profile.language=id;save();render();break;case 'onboard':go('onboard');break;
 case 'switch-role':state.profile.role=state.profile.role==='buyer'?'seller':'buyer';save();render();toast(state.profile.role==='seller'?L('Selling mode enabled','అమ్మకం మోడ్ ప్రారంభమైంది'):L('Buying mode enabled','కొనుగోలు మోడ్ ప్రారంభమైంది'));break;
 case 'location':modal(L('Choose demo area','నమూనా ప్రాంతం ఎంచుకోండి'),`<form data-form="location">${select(L('Location','ప్రాంతం'),'city',['Guntur','Mangalagiri','Vijayawada','Tenali','Ongole','Nellore','Nuzvid','Bhimavaram','Khammam'],state.profile.city)}${note('Distances and nearby listings in this prototype are fictional.','ఈ నమూనాలో దూరాలు మరియు దగ్గర లిస్టింగ్‌లు కల్పితమైనవి.')}${submit(L('Set location','ప్రాంతం ఎంచుకోండి'))}</form>`);break;
 case 'requests':go('requests');break;case 'my-requests':ui.requestTab='mine';go('requests');break;case 'request-cat':ui.requestCat=id;render();break;case 'request-tab':ui.requestTab=id;render();break;
 case 'request-detail':go('request-detail',{id});break;case 'new-request':ui.requestDraft=null;go('request-form');break;
 case 'fill-request':{const r=clone(MD.requests[0]);ui.requestDraft={...r,expires:future(7),location:state.profile.city};render();break;}
 case 'close-request':{const r=getRequest(id);r.status='closed';save();toast(L('Requirement closed','అవసరం మూసివేయబడింది'));go('requests',{},true);break;}
 case 'rfq-quote':go('offer',{requestId:id});break;
 case 'sample-rfq-quote':{const r=getRequest(id),l=state.listings.find(l=>l.cat===r.cat&&l.unit===r.unit&&available(l)),qty=Math.min(r.quantity,l?.quantity||r.quantity);const q=makeDeal(l||{title:r.title,cat:r.cat,image:cat(r.cat).image,unit:r.unit,price:r.budget,location:r.location,seller:'S1'},qty,Math.min(l?.price||r.budget,r.budget),r.location);q.requestId=r.id;q.buyer=state.profile.name;state.deals.unshift(q);save();go('deal',{id:q.id});break;}
 case 'offer':if(p&&!available(p)){toast(L('This listing is not currently available.','ఈ లిస్టింగ్ ప్రస్తుతం లభ్యం కాదు.'));break;}go('offer',{id});break;
 case 'start-sell':ui.draft=newDraft();state.profile.role='seller';save();go('sell',{step:1});break;
 case 'sell-category':ui.draft=newDraft(id);go('sell',{step:2},true);break;
 case 'sell-step':captureDraft();go('sell',{step:Number(id)},true);break;
 case 'fill-sell':{const s=clone(MD.listings.find(p=>p.cat===ui.draft.cat));Object.assign(ui.draft,{title:s.title,price:s.price,quantity:s.quantity,min:s.min,unit:s.unit,image:s.image,location:s.location,state:s.state,description:s.description,specValues:s.specs.map(v=>v[1]),expires:future(14)});render();break;}
 case 'photos':captureDraft();photoModal();break;case 'photo-select':ui.draft.image=id;closeModal();render();break;
 case 'voice-listing':voiceModal();break;
 case 'manage-listings':go('manage-listings');break;
 case 'edit-listing':ui.draft={...clone(p),specValues:p.specs.map(v=>v[1]),editId:p.id};go('sell',{step:2});break;
 case 'toggle-listing':p.status=p.status==='active'?'paused':'active';save();render();toast(L('Listing visibility updated','లిస్టింగ్ లభ్యత మార్చబడింది'));break;
 case 'sold-listing':p.status='sold';save();render();toast(L('Marked sold and removed from active marketplace','అమ్మినట్లు గుర్తించి మార్కెట్ నుంచి తొలగించబడింది'));break;
 case 'renew-listing':p.expires=future(14);p.status='active';save();render();toast(L('Listing renewed for 14 days','లిస్టింగ్ 14 రోజులు పొడిగించబడింది'));break;
 case 'expire-listing':p.expires=future(-1);save();render();break;
 case 'sample-verify':p.identity=p.identity==='sample'?'none':'sample';save();render();toast(L('Sample identity badge changed','నమూనా గుర్తింపు బ్యాడ్జ్ మార్చబడింది'));break;
 case 'deals':go('deals');break;case 'deal-tab':ui.dealTab=id;render();break;case 'deal':go('deal',{id});break;
 case 'accept-quote':if(d.stage!=='quote')break;d.stage='inspection';notify('Demo offer accepted','నమూనా ప్రతిపాదన అంగీకరించబడింది','deal',{id});save();render();toast(L('Sample acceptance recorded','నమూనా అంగీకారం నమోదైంది'));break;
 case 'counteroffer':modal(L('Sample counteroffer','నమూనా మారుప్రతిపాదన'),`<form data-form="counteroffer" data-id="${id}">${field(L('Counter price per unit (₹)','మారుప్రతిపాదన యూనిట్ ధర (₹)'),'price',Math.round(d.price*1.04*100)/100,'number','required min="0.01" step="0.01"')}${note('This demonstrates a seller response without contacting a real seller.','ఇది నిజమైన విక్రేతను సంప్రదించకుండా విక్రేత స్పందన చూపిస్తుంది.')}${errorBox()}${submit(L('Record demo counteroffer','నమూనా మారుప్రతిపాదన నమోదు'))}</form>`);break;
 case 'book-inspection':go('inspection',{id});break;case 'inspection-results':go('inspection-results',{id});break;
 case 'skip-inspection':d.inspectionSkipped=true;d.stage='agreement';save();render();break;
 case 'agreement':go('agreement',{id});break;case 'payment':go('payment',{id});break;
 case 'pickup-payment':d.paymentTerms='Payment on pickup';d.stage='transport';save();render();toast(L('Payment on pickup recorded in demo','పికప్ చెల్లింపు నమూనా నమోదైంది'));break;
 case 'transport':go('transport',{id});break;
 case 'pickup':if(d.disputed){toast(L('Resolve the open dispute first.','ముందు వివాదం పరిష్కరించండి.'));break;}d.delivery.phase='In transit';d.delivery.pickedAt=Date.now();save();render();toast(L('Demo pickup recorded','నమూనా పికప్ నమోదైంది'));break;
 case 'receipt':if(d.disputed){toast(L('Resolve the dispute in Support before completing.','పూర్తి చేసే ముందు సపోర్ట్‌లో వివాదం పరిష్కరించండి.'));break;}go('receipt',{id});break;
 case 'rating':modal(L('Rate the demo trade','నమూనా వ్యాపారానికి రేటింగ్'),`<form data-form="rating" data-id="${id}"><div class="rating-stars">${[1,2,3,4,5].map(n=>`<button type="button" class="on" data-action="rating-star" data-id="${n}" aria-label="${n} stars">★</button>`).join('')}</div><input type="hidden" name="rating" id="rating-input" value="5">${textarea(L('Your sample review','మీ నమూనా సమీక్ష'),'review','','required maxlength="600"')}${errorBox()}${submit(L('Save demo review','నమూనా సమీక్ష సేవ్ చేయండి'))}</form>`);break;
 case 'rating-star':document.getElementById('rating-input').value=id;document.querySelectorAll('[data-action="rating-star"]').forEach(el=>el.classList.toggle('on',Number(el.dataset.id)<=Number(id)));break;
 case 'chat-listing':openChat(id,seller(p.seller).name);break;case 'chat-deal':openChat(d.listingId||'RFQ-'+d.requestId,state.profile.name===d.seller?d.buyer:d.seller);break;
 case 'inbox':go('inbox');break;case 'open-chat':go('chat',{id});break;case 'quick-chat':{const c=state.chats.find(c=>c.id===ui.params.id);sendMessage(c,id);break;}
 case 'call-demo':modal(L('Call preview','కాల్ నమూనా'),`<div class="success"><div class="seal">${icon('user')}</div><h2>${esc(seller(p.seller).name)}</h2><p>${L('Demo seller contact preview. No phone call is placed. A production app can use consent-based contact sharing or masked calling.','నమూనా విక్రేత సంప్రదింపు ప్రివ్యూ. నిజమైన ఫోన్ కాల్ జరగదు.')}</p>${btn(L('Continue in demo chat','నమూనా చాట్‌లో కొనసాగండి'),'chat-listing',id)}</div>`);break;
 case 'share-listing':{const text=`Agromitra Market — DEMO listing\n${p.title}\n${money(p.price)} / ${p.unit}\nAvailable: ${p.quantity} ${p.unit}\nLocation: ${p.location}\nThis is an offline prototype. No public listing URL exists.`;modal(L('Share listing preview','లిస్టింగ్ షేర్ నమూనా'),`<p>${L('Copy the listing summary. Public listing links require a live marketplace.','లిస్టింగ్ సారాంశం కాపీ చేయండి. పబ్లిక్ లింకులకు లైవ్ మార్కెట్ అవసరం.')}</p><textarea id="share-text" style="width:100%;height:190px;padding:13px;border:1px solid var(--line);border-radius:13px;margin:15px 0" readonly>${esc(text)}</textarea>${btn(L('Copy listing summary','లిస్టింగ్ సారాంశం కాపీ'),'copy-summary')}`);break;}
 case 'copy-summary':{const el=document.getElementById('share-text');el.select();const ok=document.execCommand&&document.execCommand('copy');toast(ok?L('Summary copied','సారాంశం కాపీ అయింది'):L('Select the summary text and copy it.','సారాంశం ఎంపిక చేసి కాపీ చేయండి.'));break;}
 case 'listing-report':go('document',{id,kind:'listing'});break;case 'deal-document':go('document',{id,kind:'deal'});break;case 'inspection-document':go('document',{id,kind:'inspection'});break;
 case 'print-document':if(window.ExportBridge&&typeof window.ExportBridge.printPdf==='function')window.ExportBridge.printPdf('Agromitra_Market_SAMPLE_'+ui.params.id);else if(typeof window.print==='function')window.print();break;
 case 'report-listing':go('ticket',{listingId:id});break;case 'dispute':go('ticket',{dealId:id});break;case 'new-ticket':go('ticket');break;
 case 'resolve-ticket':{const t=state.tickets.find(t=>t.id===id);modal(L('Resolve demo ticket','నమూనా టికెట్ పరిష్కారం'),`<form data-form="resolution" data-id="${id}">${select(L('Sample resolution','నమూనా పరిష్కారం'),'resolution',t.dealId?['Resume trade','Refund demo payments and cancel trade']:['Review completed in demo'],t.dealId?'Resume trade':'Review completed in demo')}${textarea(L('Resolution notes','పరిష్కారం వివరాలు'),'notes','Resolved for prototype demonstration.','required maxlength="600"')}${errorBox()}${submit(L('Record resolution','పరిష్కారం నమోదు'))}</form>`);break;}
 case 'support':case 'help':case 'services':case 'plans':case 'payments':case 'admin':case 'moderation':case 'account':case 'profile':case 'saved':case 'notifications':go(a);break;
 case 'open-notification':{const n=state.notifications.find(n=>n.id===id);n.read=true;save();go(n.route,n.params||{});break;}
 case 'read-all':state.notifications.forEach(n=>n.read=true);save();render();break;
 case 'activate-plan':modal(L('Sample plan activation','నమూనా ప్లాన్ ప్రారంభం'),`${note('₹499/month is an illustrative price. No payment or automatic renewal occurs.','₹499/నెల నమూనా ధర. చెల్లింపు లేదా ఆటో రెన్యూవల్ జరగదు.',true)}${btn(L('Activate demo Buyer Pro','నమూనా బయ్యర్ ప్రో ప్రారంభం'),'confirm-plan')}`);break;
 case 'confirm-plan':state.subscription={name:'Buyer Pro demo',date:today(),price:499};save();closeModal();render();toast(L('Demo plan activated','నమూనా ప్లాన్ ప్రారంభమైంది'));break;
 case 'reset-confirm':modal(L('Reset demo data?','నమూనా డేటా రీసెట్?'),`<p>${L('This removes your locally created demo listings, chats, deals and settings, then restores the sample data.','మీ స్థానిక నమూనా లిస్టింగ్‌లు, చాట్‌లు, ఒప్పందాలు మరియు సెట్టింగ్‌లు తొలగించి తొలి డేటా ఇస్తుంది.')}</p><div class="btn-row">${btn(L('Keep my data','నా డేటా ఉంచండి'),'close-modal','','secondary')}${btn(L('Reset demo','నమూనా రీసెట్'),'confirm-reset','','danger')}</div>`);break;
 case 'confirm-reset':state=initialState();save();ui.stack=[];ui.draft=null;ui.filters={cat:'all',query:'',distance:0,price:0,quality:'all',sort:'recent',location:'All'};go('welcome',{},true);break;
 default:toast(L('This action is unavailable.','ఈ చర్య లభ్యం లేదు.'));
}}
function makeDeal(p,quantity,price,location){return {id:uid('D'),listingId:p.id||null,title:p.title,cat:p.cat,image:p.image,quantity:Number(quantity),unit:p.unit,price:Number(price),buyer:state.profile.name,seller:seller(p.seller||'S1').name,location,stage:'quote',created:Date.now(),payments:[],terms:null,inspection:null,delivery:null};}
function validNumber(n){return Number.isFinite(Number(n))&&Number(n)>0;}
function discreteQuantity(q,u){return !['animal','bird','egg','fish'].includes(u)||Number.isInteger(Number(q));}
function handleForm(type,o,meta={}){let d=getDeal(meta.id),p=getListing(meta.id);switch(type){
 case 'onboard':if(!o.name?.trim()||!o.agree)return error(L('Enter a name and confirm the prototype notice.','పేరు నమోదు చేసి నమూనా నోటీసు అంగీకరించండి.'));Object.assign(state.profile,{name:o.name.trim(),role:o.role,business:o.business,city:o.city,onboarded:true});save();ui.stack=[];go('home',{},true);break;
 case 'profile':if(!o.name?.trim())return error('Enter your name.');Object.assign(state.profile,{name:o.name.trim(),business:o.business,city:o.city,language:o.language});save();go('account',{},true);toast(L('Profile saved','ప్రొఫైల్ సేవ్ అయింది'));break;
 case 'location':state.profile.city=o.city;save();closeModal();render();break;
 case 'search':ui.filters.query=o.query?.trim()||'';ui.filters.cat='all';go('browse');break;
 case 'filters':ui.filters={...ui.filters,location:o.location,distance:Number(o.distance)||0,price:Number(o.price)||0,quantity:Number(o.quantity)||0,unit:o.unit,quality:o.quality,sort:o.sort};closeModal();render();break;
 case 'sell-basic':if(!o.title?.trim()||o.title.trim().length<3||!validNumber(o.price)||!validNumber(o.quantity)||!validNumber(o.min))return error(L('Enter a title, positive price, quantity and minimum order.','పేరు, సరైన ధర, పరిమాణం మరియు కనీస ఆర్డర్ నమోదు చేయండి.'));if(Number(o.min)>Number(o.quantity))return error(L('Minimum order cannot exceed available quantity.','కనీస ఆర్డర్ లభ్య పరిమాణం కంటే ఎక్కువ ఉండకూడదు.'));if(!discreteQuantity(o.quantity,o.unit)||!discreteQuantity(o.min,o.unit))return error(L('Animals, birds, eggs and fish seed use whole-number quantities.','జంతువులు, కోళ్లు, గుడ్లు మరియు చేప పిల్లలకు పూర్ణ సంఖ్య నమోదు చేయండి.'));if(!o.location?.trim()||o.expires<today())return error(L('Enter a location and a current or future expiry date.','ప్రాంతం మరియు సరైన గడువు నమోదు చేయండి.'));Object.assign(ui.draft,{title:o.title.trim(),quantity:Number(o.quantity),price:Number(o.price),min:Number(o.min),unit:o.unit,location:o.location.trim(),state:o.state,expires:o.expires});go('sell',{step:3},true);break;
 case 'sell-details':if([0,1,2,3].some(i=>!o['spec'+i]?.trim())||!o.description?.trim()||o.description.trim().length<10)return error(L('Complete the four details and a clear description.','నాలుగు వివరాలు మరియు స్పష్టమైన వివరణ నమోదు చేయండి.'));ui.draft.specValues=[0,1,2,3].map(i=>o['spec'+i].trim());ui.draft.description=o.description.trim();go('sell',{step:4},true);break;
 case 'sell-publish':{if(!o.confirmed)return error(L('Confirm the listing details first.','ముందు లిస్టింగ్ వివరాలు నిర్ధారించండి.'));const dr=ui.draft,id=dr.editId||uid('L'),old=dr.editId?getListing(id):null;const item={...(old||{}),id,cat:dr.cat,title:dr.title,te:'',price:Number(dr.price),quantity:Number(dr.quantity),min:Number(dr.min),unit:dr.unit,image:dr.image,seller:'ME',location:dr.location,state:dr.state,distance:12,sub:cat(dr.cat).name,specs:DETAIL_FIELDS[dr.cat].map((k,i)=>[k[0],dr.specValues[i]]),description:dr.description,quality:'declared',identity:old?.identity||'none',status:'active',created:old?.created||Date.now(),expires:dr.expires,own:true};if(old)state.listings[state.listings.indexOf(old)]=item;else state.listings.unshift(item);notify('Your demo listing is available','మీ నమూనా లిస్టింగ్ లభిస్తుంది','detail',{id});save();ui.draft=null;ui.stack=[];go('success',{listingId:id,title:L('Your listing is ready.','మీ లిస్టింగ్ సిద్ధంగా ఉంది.')},true);break;}
 case 'voice':{const p=MD.listings.find(p=>p.cat===o.category),numbers=(o.transcript||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/g)||[];if(numbers.length<2)return error(L('Use a quantity and price in the sample transcript.','నమూనా వాక్యంలో పరిమాణం మరియు ధర నమోదు చేయండి.'));ui.draft=newDraft(o.category);Object.assign(ui.draft,{title:p.title,quantity:Number(numbers[0]),price:Number(((o.transcript||'').match(/₹\s*([\d,]+(?:\.\d+)?)/)||[])[1]?.replace(/,/g,'')||numbers[1]),min:Math.min(p.min,Number(numbers[0])),unit:p.unit,image:p.image,location:p.location,state:p.state,specValues:p.specs.map(v=>v[1]),description:'Sample voice transcript: '+o.transcript});closeModal();go('sell',{step:2},true);toast(L('Sample fields prepared. Review and edit before publishing.','నమూనా వివరాలు సిద్ధం. ప్రచురించే ముందు మార్చండి.'));break;}
 case 'request':if(!o.title?.trim()||!validNumber(o.quantity)||!validNumber(o.budget)||!o.location?.trim()||!o.note?.trim()||o.expires<today())return error(L('Enter all required details and positive quantity / budget.','అవసరమైన వివరాలు, సరైన పరిమాణం మరియు బడ్జెట్ నమోదు చేయండి.'));if(!discreteQuantity(o.quantity,o.unit))return error(L('Use a whole-number quantity for this unit.','ఈ యూనిట్‌కు పూర్ణ సంఖ్య నమోదు చేయండి.'));{const r={id:uid('R'),cat:o.cat,title:o.title.trim(),te:'',quantity:Number(o.quantity),unit:o.unit,budget:Number(o.budget),location:o.location.trim(),buyer:state.profile.name,purpose:o.purpose,note:o.note.trim(),expires:o.expires,own:true,status:'open'};state.requests.unshift(r);save();ui.requestDraft=null;ui.stack=[];go('request-detail',{id:r.id},true);}break;
 case 'offer':{const r=getRequest(meta.requestId),q=Number(o.quantity),pr=Number(o.price);if(!validNumber(q)||!validNumber(pr)||!o.location?.trim()||o.date<today())return error(L('Enter a valid quantity, price, location and date.','సరైన పరిమాణం, ధర, ప్రాంతం మరియు తేదీ నమోదు చేయండి.'));if(p&&(!available(p)||q<p.min||q>p.quantity))return error(L('Offer quantity must be within the available lot and minimum order.','ప్రతిపాదన పరిమాణం కనీస ఆర్డర్ మరియు లభ్య పరిమాణం మధ్య ఉండాలి.'));const item=p||{title:r.title,cat:r.cat,image:cat(r.cat).image,unit:r.unit,price:r.budget,location:r.location,seller:'ME'};if(!discreteQuantity(q,item.unit))return error(L('Use a whole-number quantity for this unit.','ఈ యూనిట్‌కు పూర్ణ సంఖ్య నమోదు చేయండి.'));const dd=makeDeal(item,q,pr,o.location.trim());dd.preferredDate=o.date;dd.message=o.message;if(r){dd.requestId=r.id;dd.buyer=r.buyer;dd.seller=state.profile.name;}state.deals.unshift(dd);notify('New local demo quote created','కొత్త స్థానిక నమూనా ప్రతిపాదన','deal',{id:dd.id});save();go('deal',{id:dd.id},true);break;}
 case 'counteroffer':if(d.stage!=='quote'||!validNumber(o.price))return error('Enter a valid counter price.');d.price=Number(o.price);d.counteroffer=true;save();closeModal();render();toast(L('Sample counteroffer recorded. Accept to continue.','నమూనా మారుప్రతిపాదన నమోదైంది. కొనసాగడానికి అంగీకరించండి.'));break;
 case 'inspection':if(d.stage!=='inspection')return error('This deal is not at the inspection step.');if(!o.address?.trim()||o.date<today())return error('Enter the address and future date.');d.inspection={type:o.type,provider:o.provider,date:o.date,slot:o.slot,address:o.address,notes:o.notes,status:'Scheduled',fee:['cattle','smallstock','poultry'].includes(d.cat)?499:299};notify('Sample inspection booked','నమూనా తనిఖీ బుక్ అయింది','deal',{id:d.id});save();go('deal',{id:d.id},true);break;
 case 'inspection-results':if(!o.ack||!o.findings?.trim())return error('Enter findings and acknowledge the sample notice.');d.inspection.status='Completed';d.inspection.outcome=o.outcome;d.inspection.findings=o.findings;d.inspection.completedAt=Date.now();if(o.outcome==='Acceptable in sample')d.stage='agreement';else d.inspection.status='Further checks needed';save();go('deal',{id:d.id},true);toast(o.outcome==='Acceptable in sample'?L('Sample report saved','నమూనా రిపోర్ట్ సేవ్ అయింది'):L('Further assessment needed; arrange another sample visit.','మరింత తనిఖీ అవసరం. మరో నమూనా సందర్శన ఏర్పాటు చేయండి.'));break;
 case 'agreement':if(d.stage!=='agreement'||!o.buyerAgree||!o.sellerAgree||!o.quality?.trim()||!o.cancellation?.trim())return error('Confirm both sample acceptances and the conditions.');d.terms={transport:o.transport,weighment:o.weighment,quality:o.quality,cancellation:o.cancellation,agreedAt:Date.now()};d.stage='payment';save();go('deal',{id:d.id},true);break;
 case 'payment':if(d.stage!=='payment'||!o.ack)return error('Confirm the sample payment notice.');d.payments.push({id:uid('PAY'),amount:Math.round(dealTotal(d)*.1*100)/100,method:o.method,kind:'Demo advance',date:today()});d.paymentTerms='10% demo advance; balance on receipt';d.stage='transport';save();go('deal',{id:d.id},true);toast(L('Fictional advance recorded. No money was charged.','కల్పిత అడ్వాన్స్ నమోదైంది. డబ్బు వసూలు చేయలేదు.'));break;
 case 'transport':if(d.stage!=='transport'||!o.check0||!o.check1||!o.check2||!o.pickup?.trim()||!o.drop?.trim()||o.date<today())return error(L('Complete pickup details and all readiness checks.','పికప్ వివరాలు మరియు తనిఖీలు పూర్తి చేయండి.'));d.delivery={partner:o.partner,pickup:o.pickup,drop:o.drop,date:o.date,slot:o.slot,phase:'Booked',fee:['cattle','smallstock','poultry'].includes(d.cat)?2500:['aqua','dairy','produce'].includes(d.cat)?1900:1500};d.stage='delivery';save();go('deal',{id:d.id},true);break;
 case 'receipt':{if(d.stage!=='delivery'||d.delivery?.phase!=='In transit'||d.disputed)return error(L('Receipt requires pickup and no open dispute.','స్వీకరణకు పికప్ మరియు వివాదం లేకపోవాలి.'));if(!o.accepted||!o.settled||!validNumber(o.quantity)||!discreteQuantity(o.quantity,d.unit))return error('Confirm acceptance, settlement and a valid quantity.');if(Number(o.quantity)!==d.quantity)return error(L('Quantity differs from the agreement. Raise a dispute or amend the trade before completing.','పరిమాణం ఒప్పందంతో వేరుగా ఉంది. పూర్తి చేసే ముందు వివాదం నమోదు చేయండి.'));const balance=remaining(d);if(balance>0)d.payments.push({id:uid('PAY'),amount:balance,method:'Fictional receipt settlement',kind:'Demo balance',date:today()});d.receipt={quantity:Number(o.quantity),notes:o.notes,date:today()};d.inventoryCommitted=true;d.delivery.phase='Delivered';d.stage='complete';const li=getListing(d.listingId);if(li&&available(li)){li.quantity=Math.max(0,li.quantity-d.quantity);if(li.quantity===0)li.status='sold';else li.min=Math.min(li.min,li.quantity);}notify('Demo trade completed','నమూనా వ్యాపారం పూర్తయింది','deal',{id:d.id});save();go('deal',{id:d.id},true);break;}
 case 'rating':if(!o.review?.trim())return error('Enter a review.');state.ratings=state.ratings.filter(r=>r.dealId!==d.id);state.ratings.push({dealId:d.id,stars:Number(o.rating),review:o.review,date:today()});save();closeModal();toast(L('Sample review saved','నమూనా సమీక్ష సేవ్ అయింది'));break;
 case 'chat':{const c=state.chats.find(c=>c.id===meta.id);sendMessage(c,o.message||'');break;}
 case 'ticket':if(!o.subject?.trim()||!o.description?.trim()||o.description.trim().length<10)return error(L('Enter a subject and at least 10 characters describing the issue.','విషయం మరియు కనీసం 10 అక్షరాల వివరాలు నమోదు చేయండి.'));{const t={id:uid('T'),subject:o.subject.trim(),reason:o.reason,description:o.description.trim(),dealId:meta.dealId||null,listingId:meta.listingId||null,status:'Open',date:today()};state.tickets.unshift(t);if(t.dealId)getDeal(t.dealId).disputed=true;save();go('support',{},true);}break;
 case 'resolution':{const t=state.tickets.find(t=>t.id===meta.id);if(!o.notes?.trim())return error('Enter resolution notes.');t.status='Resolved';t.resolution=o.resolution+': '+o.notes;if(t.dealId){const dd=getDeal(t.dealId);dd.disputed=state.tickets.some(x=>x.dealId===dd.id&&x.status==='Open');if(o.resolution==='Refund demo payments and cancel trade'){const amount=paid(dd);if(amount>0)dd.payments.push({id:uid('REF'),amount:-amount,method:'Fictional refund',kind:'Demo refund',date:today()});if(dd.inventoryCommitted){const stock=getListing(dd.listingId);if(stock){stock.quantity+=dd.quantity;if(stock.status==='sold')stock.status='active';}dd.inventoryCommitted=false;}dd.stage='cancelled';dd.cancelledAt=Date.now();if(dd.delivery)dd.delivery.phase='Cancelled';}}save();closeModal();render();break;}
 case 'promotion':{const li=getListing(o.listingId);if(!li||!li.own||!available(li))return error('Choose your active listing.');li.promoted=true;state.promotions.push({listingId:li.id,price:149,until:future(7),demo:true});save();toast(L('Sample promotion recorded','నమూనా ప్రచారం నమోదైంది'));break;}
 default:return error('Unknown form.');
}return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();handleAction(el.dataset.action,el.dataset.id||'',el);});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();handleForm(f.dataset.form,Object.fromEntries(new FormData(f)),f.dataset);});
document.addEventListener('input',e=>{if(e.target.id==='browse-search'){ui.filters.query=e.target.value;const rows=filtered();document.getElementById('result-count').textContent=rows.length+' '+L('available demo listings','లభ్యమైన నమూనా లిస్టింగ్‌లు');document.getElementById('browse-results').innerHTML=rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:empty(L('No matches','సరిపోలేవి లేవు'),L('Try another title or location.','మరో పేరు లేదా ప్రాంతం ప్రయత్నించండి.'));}if(e.target.closest('form[data-form="offer"]')){const f=e.target.closest('form'),v=Object.fromEntries(new FormData(f));document.getElementById('offer-total').textContent=L('Indicative lot value','అంచనా సరుకు విలువ')+': '+money(Number(v.quantity)*Number(v.price));}});
document.addEventListener('change',e=>{if(e.target.name==='category'&&e.target.closest('form[data-form="voice"]'))voiceModal(e.target.value);if(e.target.name==='cat'&&e.target.closest('form[data-form="request"]')){const f=e.target.closest('form');f.elements.unit.value=cat(e.target.value).unit;}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.getAttribute('role')==='button'&&e.target.dataset.action){e.preventDefault();handleAction(e.target.dataset.action,e.target.dataset.id);}});
window.MarketApp={get state(){return state;},ui,render,go,handleAction,handleForm,filtered,initialState,save,STAGES};
render();
